// Задания составлены JOL-Bilim по структуре и темам ОРТ.
window.ORT_BANK = {"meta": {"source": "Задания составлены JOL-Bilim по структуре и темам ОРТ.", "version": "2026-09-30"}, "math": {"compare": [{"type": "compare", "question": "Колонка А:  5/8\nКолонка Б:  0,625", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 2, "fixedOrder": true, "explanation": "5/8 = 5 : 8 = 0,625. Величины равны."}, {"type": "compare", "question": "Колонка А:  2¹⁰\nКолонка Б:  10³", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 0, "fixedOrder": true, "explanation": "2¹⁰ = 1024, 10³ = 1000. 1024 > 1000, значит больше А."}, {"type": "compare", "question": "Колонка А:  √50\nКолонка Б:  7", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 0, "fixedOrder": true, "explanation": "7 = √49, а √50 > √49. Значит больше А."}, {"type": "compare", "question": "Колонка А:  15% от 80\nКолонка Б:  80% от 15", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 2, "fixedOrder": true, "explanation": "15% от 80 = 0,15 · 80 = 12; 80% от 15 = 0,8 · 15 = 12. Равны (a% от b всегда равно b% от a)."}, {"type": "compare", "question": "x > 0\n\nКолонка А:  x\nКолонка Б:  x²", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 3, "fixedOrder": true, "explanation": "При x = 2: x² = 4 > 2 (больше Б). При x = 0,5: x² = 0,25 < 0,5 (больше А). При x = 1 равны. Ответ однозначно определить нельзя."}, {"type": "compare", "question": "Колонка А:  (−2)⁵\nКолонка Б:  (−3)³", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 1, "fixedOrder": true, "explanation": "(−2)⁵ = −32, (−3)³ = −27. −27 > −32, значит больше Б."}, {"type": "compare", "question": "Колонка А:  Сумма углов треугольника\nКолонка Б:  Половина суммы углов четырёхугольника", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 2, "fixedOrder": true, "explanation": "Сумма углов треугольника 180°, четырёхугольника 360°, половина — 180°. Равны."}, {"type": "compare", "question": "a и b — натуральные числа, a + b = 10\n\nКолонка А:  a · b\nКолонка Б:  25", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 3, "fixedOrder": true, "explanation": "Произведение наибольшее при a = b = 5: 25. При a = 1, b = 9 получится 9 < 25. Может быть и равно, и меньше — определить нельзя."}, {"type": "compare", "question": "Колонка А:  0,3²\nКолонка Б:  0,3", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 1, "fixedOrder": true, "explanation": "0,3² = 0,09 < 0,3. Квадрат числа между 0 и 1 меньше самого числа."}, {"type": "compare", "question": "Колонка А:  Количество простых чисел от 1 до 20\nКолонка Б:  8", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 2, "fixedOrder": true, "explanation": "Простые числа до 20: 2, 3, 5, 7, 11, 13, 17, 19 — их 8. Равны."}, {"type": "compare", "question": "Колонка А:  Периметр квадрата со стороной 5\nКолонка Б:  Длина окружности радиуса 3", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 0, "fixedOrder": true, "explanation": "Периметр = 4 · 5 = 20. Длина окружности = 2π · 3 ≈ 18,85. Больше А."}, {"type": "compare", "question": "x = −3\n\nКолонка А:  x²\nКолонка Б:  −x³", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 1, "fixedOrder": true, "explanation": "x² = 9; −x³ = −(−27) = 27. Больше Б."}, {"type": "compare", "question": "Колонка А:  1/3 + 1/6\nКолонка Б:  1/2", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 2, "fixedOrder": true, "explanation": "1/3 + 1/6 = 2/6 + 1/6 = 3/6 = 1/2. Равны."}, {"type": "compare", "question": "2x + 3 = 11\n\nКолонка А:  x\nКолонка Б:  4", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 2, "fixedOrder": true, "explanation": "2x = 8, x = 4. Равны."}, {"type": "compare", "question": "Колонка А:  7! / 5!\nКолонка Б:  40", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 0, "fixedOrder": true, "explanation": "7!/5! = 7 · 6 = 42 > 40. Больше А."}, {"type": "compare", "question": "Колонка А:  Площадь круга радиуса 2\nКолонка Б:  12", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 0, "fixedOrder": true, "explanation": "S = π · 2² = 4π ≈ 12,57 > 12. Больше А."}, {"type": "compare", "question": "a < 0 < b\n\nКолонка А:  a · b\nКолонка Б:  0", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 1, "fixedOrder": true, "explanation": "Произведение отрицательного и положительного числа отрицательно, т.е. меньше 0. Больше Б."}, {"type": "compare", "question": "Колонка А:  Среднее арифметическое чисел 4, 8 и 12\nКолонка Б:  8", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 2, "fixedOrder": true, "explanation": "(4 + 8 + 12) : 3 = 24 : 3 = 8. Равны."}, {"type": "compare", "question": "y > 1\n\nКолонка А:  1/y\nКолонка Б:  y", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 1, "fixedOrder": true, "explanation": "Если y > 1, то 1/y < 1 < y. Больше Б."}, {"type": "compare", "question": "Колонка А:  3⁴\nКолонка Б:  4³", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 0, "fixedOrder": true, "explanation": "3⁴ = 81, 4³ = 64. Больше А."}, {"type": "compare", "question": "Колонка А:  0,1% от 5000\nКолонка Б:  5", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 2, "fixedOrder": true, "explanation": "0,1% = 0,001; 0,001 · 5000 = 5. Равны."}, {"type": "compare", "question": "Стороны треугольника равны 3, 4 и 5\n\nКолонка А:  Площадь треугольника\nКолонка Б:  6", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 2, "fixedOrder": true, "explanation": "3² + 4² = 5², треугольник прямоугольный с катетами 3 и 4. S = 3 · 4 : 2 = 6. Равны."}, {"type": "compare", "question": "n — целое число\n\nКолонка А:  n²\nКолонка Б:  n", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 3, "fixedOrder": true, "explanation": "При n = 0 и n = 1 величины равны, при n = 2 или n = −1 больше А. Однозначно определить нельзя."}, {"type": "compare", "question": "Колонка А:  2/3\nКолонка Б:  0,67", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 1, "fixedOrder": true, "explanation": "2/3 = 0,666… < 0,67. Больше Б."}, {"type": "compare", "question": "Цену товара повысили на 20%, а затем снизили на 20%\n\nКолонка А:  Итоговая цена\nКолонка Б:  Первоначальная цена", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 1, "fixedOrder": true, "explanation": "Итог = цена · 1,2 · 0,8 = 0,96 цены, т.е. на 4% меньше первоначальной. Больше Б."}, {"type": "compare", "question": "Колонка А:  √(16 + 9)\nКолонка Б:  √16 + √9", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 1, "fixedOrder": true, "explanation": "√25 = 5, а √16 + √9 = 4 + 3 = 7. Больше Б. Корень из суммы не равен сумме корней."}, {"type": "compare", "question": "x² = 9\n\nКолонка А:  x\nКолонка Б:  3", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 3, "fixedOrder": true, "explanation": "x = 3 или x = −3. В первом случае равны, во втором больше Б — определить нельзя."}, {"type": "compare", "question": "Колонка А:  Количество диагоналей шестиугольника\nКолонка Б:  9", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 2, "fixedOrder": true, "explanation": "Число диагоналей n-угольника: n(n − 3)/2 = 6 · 3 / 2 = 9. Равны."}, {"type": "compare", "topic": "Дроби и десятичные", "question": "Колонка А:  0,78\nКолонка Б:  7/9", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 0, "fixedOrder": true, "explanation": "7/9 = 0,777… , а 0,78 = 0,780. 0,780 > 0,777…, значит больше А."}, {"type": "compare", "topic": "Корни", "question": "Колонка А:  √2 + √8\nКолонка Б:  √18", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 2, "fixedOrder": true, "explanation": "√8 = 2√2, поэтому √2 + √8 = 3√2. √18 = √(9 · 2) = 3√2. Величины равны."}, {"type": "compare", "topic": "Проценты", "question": "Колонка А:  30% от 30% от 200\nКолонка Б:  18", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 2, "fixedOrder": true, "explanation": "30% от 200 = 60; 30% от 60 = 18. Величины равны."}, {"type": "compare", "topic": "Алгебра с условием", "question": "x < 0\n\nКолонка А:  x³\nКолонка Б:  x²", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 1, "fixedOrder": true, "explanation": "При x < 0 куб отрицателен, а квадрат положителен: x³ < 0 < x². Больше Б."}, {"type": "compare", "topic": "Алгебра с условием", "question": "a > b\n\nКолонка А:  a²\nКолонка Б:  b²", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 3, "fixedOrder": true, "explanation": "При a = 3, b = 1: a² = 9 > 1 (больше А). При a = 1, b = −3: a² = 1 < 9 (больше Б). Определить нельзя."}, {"type": "compare", "topic": "Углы треугольника", "question": "В равнобедренном треугольнике угол при вершине равен 40°\n\nКолонка А:  Угол при основании\nКолонка Б:  70°", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 2, "fixedOrder": true, "explanation": "Углы при основании равны: (180° − 40°) : 2 = 70°. Величины равны."}, {"type": "compare", "topic": "Площади фигур", "question": "Колонка А:  Площадь квадрата с диагональю 6\nКолонка Б:  Площадь прямоугольника со сторонами 4 и 5", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 1, "fixedOrder": true, "explanation": "Площадь квадрата равна половине квадрата диагонали: 6² : 2 = 18. Площадь прямоугольника 4 · 5 = 20. Больше Б."}, {"type": "compare", "topic": "Неравенство треугольника", "question": "Две стороны треугольника равны 3 и 7\n\nКолонка А:  Третья сторона\nКолонка Б:  5", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 3, "fixedOrder": true, "explanation": "Третья сторона лежит между 7 − 3 = 4 и 7 + 3 = 10. Она может быть 4,5 (больше Б) или 9 (больше А). Определить нельзя."}, {"type": "compare", "topic": "Вероятность", "question": "Колонка А:  Вероятность того, что при двух бросках монеты оба раза выпадет орёл\nКолонка Б:  Вероятность того, что на игральном кубике выпадет 6", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 0, "fixedOrder": true, "explanation": "Два орла: 1/2 · 1/2 = 1/4. Шестёрка на кубике: 1/6. 1/4 > 1/6, значит больше А."}, {"type": "compare", "topic": "Среднее и медиана", "question": "Даны числа: 2, 3, 3, 8, 14\n\nКолонка А:  Медиана этих чисел\nКолонка Б:  Среднее арифметическое этих чисел", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 1, "fixedOrder": true, "explanation": "Медиана (среднее по порядку число) равна 3. Среднее: (2 + 3 + 3 + 8 + 14) : 5 = 30 : 5 = 6. Больше Б."}, {"type": "compare", "topic": "Степени и корни", "question": "0 < x < 1\n\nКолонка А:  √x\nКолонка Б:  x", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 0, "fixedOrder": true, "explanation": "Для 0 < x < 1 корень больше самого числа, например √0,25 = 0,5 > 0,25. Больше А."}, {"type": "compare", "topic": "Среднее арифметическое", "question": "Среднее арифметическое чисел 6, 10 и x больше 8\n\nКолонка А:  x\nКолонка Б:  9", "options": ["Величина в колонке А больше", "Величина в колонке Б больше", "Величины равны", "Недостаточно информации, чтобы определить"], "correctIndex": 3, "fixedOrder": true, "explanation": "Из (6 + 10 + x) : 3 > 8 следует x > 8. При x = 8,5 больше Б, при x = 20 больше А. Определить нельзя."}], "standard": [{"type": "standard", "question": "Вычислите: 2,5 · 0,4 + 1,5", "options": ["2,5", "1,9", "3", "1", "2,9"], "correctIndex": 0, "explanation": "2,5 · 0,4 = 1; 1 + 1,5 = 2,5."}, {"type": "standard", "question": "Найдите 35% от 240.", "options": ["84", "70", "96", "72", "90"], "correctIndex": 0, "explanation": "0,35 · 240 = 84."}, {"type": "standard", "question": "Решите уравнение: 3(x − 2) = x + 8", "options": ["7", "5", "3", "−7", "1"], "correctIndex": 0, "explanation": "3x − 6 = x + 8 → 2x = 14 → x = 7."}, {"type": "standard", "question": "Упростите выражение: a² · a³ : a⁴", "options": ["a", "a²", "a⁵", "a⁹", "1"], "correctIndex": 0, "explanation": "a² · a³ = a⁵; a⁵ : a⁴ = a¹ = a."}, {"type": "standard", "question": "После увеличения на 25% число стало равно 150. Каким было исходное число?", "options": ["120", "112,5", "125", "187,5", "100"], "correctIndex": 0, "explanation": "Исходное · 1,25 = 150 → исходное = 150 : 1,25 = 120."}, {"type": "standard", "question": "Вычислите: 2⁻³", "options": ["1/8", "−8", "−1/8", "8", "1/6"], "correctIndex": 0, "explanation": "2⁻³ = 1/2³ = 1/8."}, {"type": "standard", "question": "Вычислите: √121 − √0,25", "options": ["10,5", "11,25", "10,75", "10", "11,5"], "correctIndex": 0, "explanation": "√121 = 11, √0,25 = 0,5. 11 − 0,5 = 10,5."}, {"type": "standard", "question": "Решите неравенство: 5 − 2x > 11", "options": ["x < −3", "x > −3", "x < 3", "x > 3", "x < −8"], "correctIndex": 0, "explanation": "−2x > 6. При делении на отрицательное число знак меняется: x < −3."}, {"type": "standard", "question": "Средний возраст трёх братьев — 12 лет. Двум из них 10 и 11 лет. Сколько лет третьему?", "options": ["15", "12", "13", "14", "16"], "correctIndex": 0, "explanation": "Сумма возрастов 3 · 12 = 36. 36 − 10 − 11 = 15."}, {"type": "standard", "question": "В классе 12 мальчиков и 18 девочек. Какую часть класса составляют мальчики?", "options": ["2/5", "2/3", "3/5", "1/3", "3/4"], "correctIndex": 0, "explanation": "12 : 30 = 2/5."}, {"type": "standard", "question": "Найдите произведение корней уравнения x² − 7x + 10 = 0.", "options": ["10", "7", "−10", "−7", "17"], "correctIndex": 0, "explanation": "Корни 2 и 5 (по теореме Виета произведение равно свободному члену): 2 · 5 = 10."}, {"type": "standard", "question": "Функция задана формулой y = 2x − 3. При каком x значение y равно 7?", "options": ["5", "2", "11", "−2", "4"], "correctIndex": 0, "explanation": "2x − 3 = 7 → 2x = 10 → x = 5."}, {"type": "standard", "question": "Поезд прошёл 240 км за 3 часа. За сколько часов он пройдёт 400 км с той же скоростью?", "options": ["5", "4", "6", "4,5", "5,5"], "correctIndex": 0, "explanation": "Скорость 240 : 3 = 80 км/ч. 400 : 80 = 5 ч."}, {"type": "standard", "question": "Два числа относятся как 3 : 5, а их сумма равна 64. Найдите большее число.", "options": ["40", "24", "32", "38", "45"], "correctIndex": 0, "explanation": "Всего 3 + 5 = 8 частей, одна часть 64 : 8 = 8. Большее: 5 · 8 = 40."}, {"type": "standard", "question": "Сколькими способами из 6 человек можно выбрать старосту и его заместителя?", "options": ["30", "15", "36", "12", "11"], "correctIndex": 0, "explanation": "Старосту выбираем 6 способами, заместителя — из оставшихся 5: 6 · 5 = 30 (порядок важен)."}, {"type": "standard", "question": "Бросают игральный кубик. Какова вероятность, что выпадет число больше 4?", "options": ["1/3", "1/2", "1/6", "2/3", "1/4"], "correctIndex": 0, "explanation": "Подходят 5 и 6 — 2 исхода из 6: 2/6 = 1/3."}, {"type": "standard", "question": "Найдите наибольший общий делитель чисел 84 и 36.", "options": ["12", "6", "4", "18", "252"], "correctIndex": 0, "explanation": "84 = 2² · 3 · 7, 36 = 2² · 3². НОД = 2² · 3 = 12."}, {"type": "standard", "question": "Найдите наименьшее общее кратное чисел 12 и 18.", "options": ["36", "72", "6", "216", "54"], "correctIndex": 0, "explanation": "12 = 2² · 3, 18 = 2 · 3². НОК = 2² · 3² = 36."}, {"type": "standard", "question": "Катеты прямоугольного треугольника равны 6 и 8. Найдите гипотенузу.", "options": ["10", "14", "12", "9", "7"], "correctIndex": 0, "explanation": "По теореме Пифагора: √(6² + 8²) = √100 = 10."}, {"type": "standard", "question": "Два угла треугольника равны 48° и 67°. Найдите третий угол (в градусах).", "options": ["65", "75", "55", "115", "45"], "correctIndex": 0, "explanation": "180 − 48 − 67 = 65."}, {"type": "standard", "question": "Основания трапеции равны 6 и 10, высота 5. Найдите площадь трапеции.", "options": ["40", "80", "30", "50", "60"], "correctIndex": 0, "explanation": "S = (6 + 10) : 2 · 5 = 40."}, {"type": "standard", "question": "Длина окружности равна 18π. Найдите площадь круга.", "options": ["81π", "18π", "36π", "324π", "9π"], "correctIndex": 0, "explanation": "2πr = 18π → r = 9. S = πr² = 81π."}, {"type": "standard", "question": "Один из смежных углов на 40° больше другого. Найдите больший угол (в градусах).", "options": ["110", "70", "140", "100", "120"], "correctIndex": 0, "explanation": "x + (x + 40) = 180 → x = 70. Больший угол 70 + 40 = 110."}, {"type": "standard", "question": "Найдите внутренний угол правильного шестиугольника (в градусах).", "options": ["120", "108", "135", "60", "150"], "correctIndex": 0, "explanation": "Сумма углов (6 − 2) · 180 = 720°; 720 : 6 = 120."}, {"type": "standard", "question": "Найдите объём куба с ребром 3 см (в см³).", "options": ["27", "9", "18", "54", "81"], "correctIndex": 0, "explanation": "V = a³ = 3³ = 27."}, {"type": "standard", "question": "Вычислите: sin 30° + cos 60°", "options": ["1", "1/2", "√3", "√3/2", "0"], "correctIndex": 0, "explanation": "sin 30° = 1/2, cos 60° = 1/2. Сумма равна 1."}, {"type": "standard", "question": "Известно, что x + y = 10 и x − y = 4. Найдите x · y.", "options": ["21", "24", "16", "25", "30"], "correctIndex": 0, "explanation": "Сложим: 2x = 14, x = 7; тогда y = 3. x · y = 21."}, {"type": "standard", "question": "Вычислите: (1/2 + 1/3) : 5/6", "options": ["1", "5/6", "25/36", "6/5", "1/2"], "correctIndex": 0, "explanation": "1/2 + 1/3 = 5/6. 5/6 : 5/6 = 1."}, {"type": "standard", "question": "Вычислите: 5⁰ + 5¹ + 5²", "options": ["31", "30", "25", "26", "36"], "correctIndex": 0, "explanation": "1 + 5 + 25 = 31."}, {"type": "standard", "question": "Цена товара 800 сом снизилась на 15%. Какой стала цена (в сомах)?", "options": ["680", "785", "120", "700", "665"], "correctIndex": 0, "explanation": "15% от 800 = 120. 800 − 120 = 680."}, {"type": "standard", "question": "В арифметической прогрессии a₁ = 3, d = 4. Найдите a₁₀.", "options": ["39", "43", "40", "36", "35"], "correctIndex": 0, "explanation": "a₁₀ = a₁ + 9d = 3 + 36 = 39."}, {"type": "standard", "question": "4 тетради стоят 72 сома. Сколько стоят 7 таких тетрадей (в сомах)?", "options": ["126", "108", "144", "112", "135"], "correctIndex": 0, "explanation": "Одна тетрадь 72 : 4 = 18 сом. 7 · 18 = 126."}, {"type": "standard", "question": "Вычислите: |−7| − |3 − 5|", "options": ["5", "9", "−5", "1", "15"], "correctIndex": 0, "explanation": "|−7| = 7, |3 − 5| = |−2| = 2. 7 − 2 = 5."}, {"type": "standard", "question": "Упростите выражение: (x + 3)² − x²", "options": ["6x + 9", "9", "6x", "2x + 9", "x² + 6x + 9"], "correctIndex": 0, "explanation": "(x + 3)² = x² + 6x + 9. Вычитаем x²: 6x + 9."}, {"type": "standard", "question": "Периметр прямоугольника 30, одна из сторон 6. Найдите его площадь.", "options": ["54", "36", "90", "45", "24"], "correctIndex": 0, "explanation": "Вторая сторона: 30 : 2 − 6 = 9. Площадь 6 · 9 = 54."}, {"type": "standard", "question": "Первый рабочий выполняет заказ за 6 часов, второй — за 3 часа. За сколько часов они выполнят заказ вместе?", "options": ["2", "4,5", "3", "1,5", "9"], "correctIndex": 0, "explanation": "За час вместе: 1/6 + 1/3 = 1/2 заказа. Весь заказ — за 2 часа."}, {"type": "standard", "topic": "Дроби", "question": "Вычислите: 2 1/3 − 3/4 · 2/3", "options": ["1 1/18", "1 2/3", "2 1/6", "1 1/6", "1 5/6"], "correctIndex": 4, "explanation": "Сначала умножение: 3/4 · 2/3 = 1/2. Затем 7/3 − 1/2 = 14/6 − 3/6 = 11/6 = 1 5/6."}, {"type": "standard", "topic": "Проценты", "question": "Вклад 20 000 сом положили в банк под 10% годовых. Проценты каждый год прибавляются к вкладу. Сколько сомов будет на счёте через 2 года?", "options": ["24 200", "24 400", "22 000", "26 620", "24 000"], "correctIndex": 0, "explanation": "После 1 года: 20 000 · 1,1 = 22 000. После 2 лет: 22 000 · 1,1 = 24 200."}, {"type": "standard", "topic": "Смеси и растворы", "question": "Смешали 300 г 20%-го раствора соли и 200 г 5%-го раствора соли. Какова концентрация соли в полученном растворе?", "options": ["12,5%", "15%", "14%", "25%", "10%"], "correctIndex": 2, "explanation": "Соли: 0,2 · 300 + 0,05 · 200 = 60 + 10 = 70 г в 500 г раствора. 70 : 500 = 0,14 = 14%."}, {"type": "standard", "topic": "Линейные уравнения", "question": "Решите уравнение: (x + 1)/2 − (x − 2)/3 = 2", "options": ["1", "13", "7", "5", "−5"], "correctIndex": 3, "explanation": "Умножим на 6: 3(x + 1) − 2(x − 2) = 12 → 3x + 3 − 2x + 4 = 12 → x = 5."}, {"type": "standard", "topic": "Квадратные неравенства", "question": "Решите неравенство: x² − 4x − 5 < 0", "options": ["(−∞; −1) ∪ (5; +∞)", "(−5; 1)", "(−∞; 5)", "[−1; 5]", "(−1; 5)"], "correctIndex": 4, "explanation": "Корни x² − 4x − 5 = 0: x = −1 и x = 5. Ветви параболы вверх, поэтому она отрицательна между корнями: −1 < x < 5 (концы не входят, неравенство строгое)."}, {"type": "standard", "topic": "Системы уравнений", "question": "Решите систему: 2x + 3y = 13, x − y = −1. Найдите x + y.", "options": ["5", "7", "1", "4", "6"], "correctIndex": 0, "explanation": "Из второго уравнения x = y − 1. Тогда 2(y − 1) + 3y = 13 → 5y = 15 → y = 3, x = 2. x + y = 5."}, {"type": "standard", "topic": "Линейная функция", "question": "Прямая y = kx + 4 проходит через точку (2; −2). Найдите k.", "options": ["1", "−3", "3", "−2", "−1"], "correctIndex": 1, "explanation": "Подставим точку: −2 = 2k + 4 → 2k = −6 → k = −3."}, {"type": "standard", "topic": "Квадратичная функция", "question": "Найдите координаты вершины параболы y = x² − 6x + 5.", "options": ["(6; 5)", "(−3; 32)", "(−3; −4)", "(3; −4)", "(3; 4)"], "correctIndex": 3, "explanation": "Абсцисса вершины x = −b/(2a) = 6/2 = 3. y(3) = 9 − 18 + 5 = −4. Вершина (3; −4)."}, {"type": "standard", "topic": "Геометрическая прогрессия", "question": "В геометрической прогрессии b₁ = 3, q = 2. Найдите сумму первых пяти членов.", "options": ["186", "48", "93", "45", "96"], "correctIndex": 2, "explanation": "Члены: 3, 6, 12, 24, 48. Сумма = 3 · (2⁵ − 1)/(2 − 1) = 3 · 31 = 93."}, {"type": "standard", "topic": "Логарифмы", "question": "Вычислите: log₂ 32 + log₃ (1/9)", "options": ["2", "−3", "7", "5", "3"], "correctIndex": 4, "explanation": "log₂ 32 = 5, так как 2⁵ = 32; log₃ (1/9) = −2, так как 3⁻² = 1/9. 5 + (−2) = 3."}, {"type": "standard", "topic": "Корни", "question": "Вычислите: (√12 − √3)²", "options": ["27", "9", "15", "3", "6"], "correctIndex": 3, "explanation": "√12 = 2√3, поэтому √12 − √3 = √3, а (√3)² = 3."}, {"type": "standard", "topic": "Тригонометрия", "question": "Известно, что sin α = 0,6 и 90° < α < 180°. Найдите cos α.", "options": ["0,75", "0,8", "0,4", "−0,4", "−0,8"], "correctIndex": 4, "explanation": "cos²α = 1 − 0,36 = 0,64, |cos α| = 0,8. Во второй четверти косинус отрицателен: cos α = −0,8."}, {"type": "standard", "topic": "Комбинаторика", "question": "Сколько различных трёхзначных чисел можно составить из цифр 1, 2, 3, 4, 5, если цифры в числе не повторяются?", "options": ["60", "120", "125", "10", "15"], "correctIndex": 0, "explanation": "Первую цифру выбираем 5 способами, вторую — 4, третью — 3: 5 · 4 · 3 = 60."}, {"type": "standard", "topic": "Вероятность", "question": "В коробке 5 красных и 3 синих шара. Наугад вынимают сразу 2 шара. Какова вероятность, что оба шара красные?", "options": ["25/64", "3/28", "5/8", "5/14", "5/16"], "correctIndex": 3, "explanation": "Способов выбрать 2 красных: C(5,2) = 10; всего способов выбрать 2 шара: C(8,2) = 28. P = 10/28 = 5/14."}, {"type": "standard", "topic": "Задачи на движение", "question": "Лодка прошла 24 км по течению реки за 2 часа, а обратно — за 3 часа. Найдите скорость течения (в км/ч).", "options": ["1", "2,5", "10", "2", "4"], "correctIndex": 3, "explanation": "Скорость по течению 12 км/ч, против течения 8 км/ч. Скорость течения = (12 − 8) : 2 = 2 км/ч."}, {"type": "standard", "topic": "Задачи на деньги", "question": "3 ручки и 2 блокнота стоят 190 сомов, а 1 ручка и 2 таких же блокнота — 130 сомов. Сколько сомов стоит один блокнот?", "options": ["45", "50", "30", "60", "40"], "correctIndex": 1, "explanation": "Разница покупок — 2 ручки, они стоят 190 − 130 = 60 сомов, ручка 30 сомов. Блокнот: (130 − 30) : 2 = 50 сомов."}, {"type": "standard", "topic": "Прямоугольный треугольник", "question": "Гипотенуза прямоугольного треугольника равна 13, один из катетов равен 5. Найдите площадь треугольника.", "options": ["32,5", "12", "30", "60", "65"], "correctIndex": 2, "explanation": "Второй катет: √(13² − 5²) = √144 = 12. Площадь = 5 · 12 : 2 = 30."}, {"type": "standard", "topic": "Окружность", "question": "Вписанный угол опирается на дугу 110°. Найдите этот угол (в градусах).", "options": ["55", "110", "125", "220", "70"], "correctIndex": 0, "explanation": "Вписанный угол равен половине дуги, на которую он опирается: 110° : 2 = 55°."}, {"type": "standard", "topic": "Многоугольники", "question": "Сумма внутренних углов выпуклого многоугольника равна 1260°. Сколько у него сторон?", "options": ["9", "11", "7", "10", "8"], "correctIndex": 0, "explanation": "Сумма углов n-угольника (n − 2) · 180°. (n − 2) · 180 = 1260 → n − 2 = 7 → n = 9."}, {"type": "standard", "topic": "Объёмы тел", "question": "Найдите объём цилиндра, радиус основания которого равен 3, а высота — 5.", "options": ["75π", "45π", "90π", "30π", "15π"], "correctIndex": 1, "explanation": "V = πr²h = π · 9 · 5 = 45π."}, {"type": "standard", "topic": "Правильный треугольник", "question": "Сторона правильного треугольника равна 6. Найдите его высоту.", "options": ["9", "3√2", "3", "6√3", "3√3"], "correctIndex": 4, "explanation": "Высота делит сторону пополам: h = √(6² − 3²) = √27 = 3√3."}, {"type": "standard", "topic": "Подобие", "question": "Площади двух подобных треугольников равны 16 и 36. Сторона меньшего треугольника равна 6. Найдите соответствующую сторону большего.", "options": ["8", "9", "13,5", "12", "24"], "correctIndex": 1, "explanation": "Отношение площадей равно квадрату коэффициента подобия: k² = 36/16, k = 3/2. Сторона 6 · 3/2 = 9."}, {"type": "standard", "topic": "Координаты на плоскости", "question": "Найдите расстояние между точками A(−1; 2) и B(5; 10).", "options": ["10", "100", "14", "12", "8"], "correctIndex": 0, "explanation": "d = √((5 − (−1))² + (10 − 2)²) = √(36 + 64) = √100 = 10."}, {"type": "standard", "topic": "Ромб", "question": "Диагонали ромба равны 10 и 24. Найдите сторону ромба.", "options": ["7", "26", "17", "13", "12"], "correctIndex": 3, "explanation": "Диагонали ромба перпендикулярны и делятся пополам: сторона = √(5² + 12²) = √169 = 13."}]}, "verbal": {"analogies": [{"type": "analogy", "question": "ВРАЧ : БОЛЬНИЦА\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["учитель : школа", "повар : блюдо", "пилот : самолёт", "художник : кисть"], "correctIndex": 0, "explanation": "Отношение «профессия — место работы»: врач работает в больнице, учитель — в школе."}, {"type": "analogy", "question": "ТЁПЛЫЙ : ГОРЯЧИЙ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["прохладный : ледяной", "светлый : тёмный", "быстрый : скорый", "мокрый : вода"], "correctIndex": 0, "explanation": "Второе слово обозначает тот же признак в большей степени: горячий «сильнее» тёплого, ледяной — прохладного."}, {"type": "analogy", "question": "КНИГА : СТРАНИЦА\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["забор : доска", "автор : роман", "тетрадь : ручка", "читатель : журнал"], "correctIndex": 0, "explanation": "Целое и одна из многих однотипных частей: книга состоит из страниц, забор — из досок."}, {"type": "analogy", "question": "ПТИЦА : ГНЕЗДО\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["пчела : улей", "лошадь : седло", "корова : молоко", "волк : стая"], "correctIndex": 0, "explanation": "Животное и его жилище: птица живёт в гнезде, пчела — в улье."}, {"type": "analogy", "question": "СМЕЛЫЙ : ТРУСЛИВЫЙ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["щедрый : жадный", "умный : мудрый", "высокий : рост", "добрый : друг"], "correctIndex": 0, "explanation": "Антонимы — слова с противоположным значением."}, {"type": "analogy", "question": "ХЛЕБ : ПЕКАРЬ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["обувь : сапожник", "лекарство : больной", "урок : ученик", "дом : улица"], "correctIndex": 0, "explanation": "Изделие и тот, кто его изготавливает: хлеб печёт пекарь, обувь шьёт сапожник."}, {"type": "analogy", "question": "ТЕРМОМЕТР : ТЕМПЕРАТУРА\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["весы : масса", "часы : будильник", "линейка : карандаш", "компас : путешествие"], "correctIndex": 0, "explanation": "Прибор и величина, которую он измеряет."}, {"type": "analogy", "question": "ГУСЕНИЦА : БАБОЧКА\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["головастик : лягушка", "утка : селезень", "птица : птенец", "яйцо : скорлупа"], "correctIndex": 0, "explanation": "Ранняя стадия развития и взрослая особь того же животного."}, {"type": "analogy", "question": "ЗАСУХА : НЕУРОЖАЙ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["ливень : наводнение", "снег : зима", "дождь : зонт", "солнце : лето"], "correctIndex": 0, "explanation": "Причина и следствие: засуха приводит к неурожаю, ливень — к наводнению."}, {"type": "analogy", "question": "СТРОКА : СТИХОТВОРЕНИЕ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["нота : мелодия", "кисть : картина", "поэт : поэма", "песня : певец"], "correctIndex": 0, "explanation": "Часть и целое: стихотворение складывается из строк, мелодия — из нот."}, {"type": "analogy", "question": "ОСЕНЬ : ЛИСТОПАД\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["зима : снегопад", "весна : сезон", "лето : июль", "утро : вечер"], "correctIndex": 0, "explanation": "Время года и характерное для него природное явление."}, {"type": "analogy", "question": "ХИРУРГ : СКАЛЬПЕЛЬ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["парикмахер : ножницы", "учитель : ученик", "водитель : пассажир", "строитель : дом"], "correctIndex": 0, "explanation": "Профессия и основной рабочий инструмент."}, {"type": "analogy", "question": "ОГРОМНЫЙ : БОЛЬШОЙ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["крошечный : маленький", "холодный : тёплый", "быстрый : медленный", "длинный : длина"], "correctIndex": 0, "explanation": "Первое слово — тот же признак, но в большей степени: огромный — «очень большой», крошечный — «очень маленький»."}, {"type": "analogy", "question": "АЛФАВИТ : БУКВА\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["созвездие : звезда", "поезд : рельсы", "слово : смысл", "море : берег"], "correctIndex": 0, "explanation": "Совокупность и её элемент: алфавит состоит из букв, созвездие — из звёзд."}, {"type": "analogy", "question": "ЛОЖЬ : ПРАВДА\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["вражда : дружба", "радость : счастье", "сила : слабый", "война : армия"], "correctIndex": 0, "explanation": "Существительные-антонимы."}, {"type": "analogy", "question": "ГЛАЗ : ЗРЕНИЕ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["ухо : слух", "рука : перчатка", "нос : лицо", "язык : слово"], "correctIndex": 0, "explanation": "Орган чувств и его функция."}, {"type": "analogy", "question": "ПОРТНОЙ : КОСТЮМ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["строитель : здание", "покупатель : магазин", "врач : пациент", "зритель : фильм"], "correctIndex": 0, "explanation": "Мастер и то, что он создаёт."}, {"type": "analogy", "question": "ТОПОР : РУБИТЬ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["пила : пилить", "игла : острый", "молоток : гвоздь", "лопата : сад"], "correctIndex": 0, "explanation": "Инструмент и действие, которое им выполняют."}, {"type": "analogy", "question": "РАЙОН : ОБЛАСТЬ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["улица : город", "житель : страна", "карта : мир", "дом : крыша"], "correctIndex": 0, "explanation": "Меньшая территориальная единица входит в большую: район — в область, улица — в город."}, {"type": "analogy", "question": "ХОЛМ : ГОРА\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["ручей : река", "дерево : лес", "дом : крыша", "снег : лёд"], "correctIndex": 0, "explanation": "Меньший и больший объект одного рода: холм — «маленькая гора», ручей — «маленькая река»."}, {"type": "analogy", "question": "ГРАММ : КИЛОГРАММ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["метр : километр", "час : минута", "литр : вода", "сантиметр : дециметр"], "correctIndex": 0, "explanation": "Единица и единица, в 1000 раз большая: 1 кг = 1000 г, 1 км = 1000 м. (Дециметр больше сантиметра лишь в 10 раз.)"}, {"type": "analogy", "question": "АПТЕКА : ЛЕКАРСТВО\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["булочная : хлеб", "школа : учитель", "стадион : игра", "банк : кассир"], "correctIndex": 0, "explanation": "Магазин и товар, который в нём продают."}, {"type": "analogy", "question": "ДЕРЕВО : СТОЛ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["глина : кувшин", "стекло : прозрачность", "металл : шахта", "ткань : швея"], "correctIndex": 0, "explanation": "Материал и изделие из него."}, {"type": "analogy", "question": "КОМПОЗИТОР : СИМФОНИЯ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["поэт : поэма", "зритель : спектакль", "певец : микрофон", "дирижёр : оркестр"], "correctIndex": 0, "explanation": "Автор и созданное им произведение."}, {"type": "analogy", "question": "КАПЛЯ : ВОДА\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["крупинка : соль", "стакан : сок", "колесо : машина", "ключ : замок"], "correctIndex": 0, "explanation": "Мельчайшая частица вещества и само вещество."}, {"type": "analogy", "question": "БЕЖАТЬ : ИДТИ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["кричать : говорить", "спать : лежать", "читать : писать", "прыгать : падать"], "correctIndex": 0, "explanation": "Первое действие — более интенсивный вариант второго: бежать — быстрее, чем идти; кричать — громче, чем говорить."}, {"type": "analogy", "question": "РОСТ : САНТИМЕТР\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["время : секунда", "скорость : автомобиль", "масса : весы", "длина : линия"], "correctIndex": 0, "explanation": "Величина и единица её измерения."}, {"type": "analogy", "question": "ЗЕРНО : МУКА\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["виноград : изюм", "яблоко : сад", "молоко : корова", "пшеница : поле"], "correctIndex": 0, "explanation": "Сырьё и продукт его переработки."}, {"type": "analogy", "question": "ЛЕКАРСТВО : БОЛЕЗНЬ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["огнетушитель : пожар", "врач : больница", "бинт : аптека", "таблетка : упаковка"], "correctIndex": 0, "explanation": "Средство и то, с чем им борются."}, {"type": "analogy", "question": "СКУПОЙ : ЩЕДРОСТЬ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["невежда : знания", "богач : деньги", "силач : сила", "учёный : наука"], "correctIndex": 0, "explanation": "Человек и качество, которого ему не хватает: скупому — щедрости, невежде — знаний."}, {"type": "analogy", "topic": "часть — целое", "question": "ЛЕПЕСТОК : ЦВЕТОК\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["спица : колесо", "роза : цветок", "бутон : цветок", "пчела : нектар"], "correctIndex": 0, "explanation": "Отношение «часть — целое»: цветок состоит из лепестков, колесо — из спиц. Роза : цветок — вид и род, бутон : цветок — стадии развития."}, {"type": "analogy", "topic": "целое — часть", "question": "ЧАСЫ : СТРЕЛКА\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["стрелка : компас", "рубашка : пуговица", "часовщик : часы", "будильник : утро"], "correctIndex": 1, "explanation": "Отношение «целое — часть»: стрелка — деталь часов, пуговица — деталь рубашки. В паре «стрелка : компас» порядок обратный."}, {"type": "analogy", "topic": "причина — следствие", "question": "ГОЛОЛЁД : ПАДЕНИЕ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["пожар : пожарный", "лёд : холодный", "землетрясение : разрушения", "каток : коньки"], "correctIndex": 2, "explanation": "Отношение «причина — следствие»: гололёд приводит к падениям, землетрясение — к разрушениям."}, {"type": "analogy", "topic": "следствие — причина", "question": "ОЖОГ : ОГОНЬ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["огонь : дым", "дым : труба", "пожарный : огонь", "опоздание : пробка"], "correctIndex": 3, "explanation": "Отношение «следствие — причина»: ожог возникает от огня, опоздание — из-за пробки. В паре «огонь : дым» порядок обратный (причина — следствие)."}, {"type": "analogy", "topic": "инструмент — действие", "question": "ВЕСЛО : ГРЕСТИ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["метла : мести", "гребец : весло", "иголка : нитка", "звонок : громкий"], "correctIndex": 0, "explanation": "Отношение «инструмент — действие»: веслом гребут, метлой метут."}, {"type": "analogy", "topic": "действие — инструмент", "question": "ШИТЬ : ИГЛА\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["игла : шить", "копать : лопата", "шить : платье", "портной : шить"], "correctIndex": 1, "explanation": "Отношение «действие — инструмент»: шьют иглой, копают лопатой. В паре «игла : шить» порядок обратный, «шить : платье» — действие и результат."}, {"type": "analogy", "topic": "синонимы", "question": "ОТВАЖНЫЙ : ХРАБРЫЙ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["весёлый : грустный", "храбрый : герой", "грустный : печальный", "тёплый : жаркий"], "correctIndex": 2, "explanation": "Синонимы — слова, близкие по значению. Тёплый : жаркий — разная степень признака, а не синонимы."}, {"type": "analogy", "topic": "синонимы", "question": "НЕПРИЯТЕЛЬ : ВРАГ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["враг : друг", "солдат : армия", "враг : вражда", "отвага : смелость"], "correctIndex": 3, "explanation": "Существительные-синонимы: неприятель — то же, что враг; отвага — то же, что смелость."}, {"type": "analogy", "topic": "антонимы", "question": "ПРИЛИВ : ОТЛИВ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["восход : закат", "шторм : буря", "волна : море", "луна : ночь"], "correctIndex": 0, "explanation": "Антонимы — противоположные явления: прилив и отлив, восход и закат. Шторм : буря — синонимы."}, {"type": "analogy", "topic": "антонимы", "question": "ВПУСКАТЬ : ВЫПУСКАТЬ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["входить : заходить", "приходить : уходить", "выпускать : выпускник", "открывать : дверь"], "correctIndex": 1, "explanation": "Глаголы-антонимы, противоположность выражена приставками: в- / вы-, при- / у-."}, {"type": "analogy", "topic": "степень признака", "question": "ДОЖДЬ : ЛИВЕНЬ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["туча : дождь", "снег : сугроб", "ветер : ураган", "гроза : молния"], "correctIndex": 2, "explanation": "Второе слово — то же явление в очень сильной степени: ливень — очень сильный дождь, ураган — очень сильный ветер."}, {"type": "analogy", "topic": "степень признака", "question": "ОБОЖАТЬ : ЛЮБИТЬ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["смеяться : плакать", "улыбаться : хохотать", "плакать : слёзы", "рыдать : плакать"], "correctIndex": 3, "explanation": "Первое действие — более сильная степень второго: обожать — очень сильно любить, рыдать — очень сильно плакать. В паре «улыбаться : хохотать» порядок обратный."}, {"type": "analogy", "topic": "профессия — результат", "question": "ФОТОГРАФ : СНИМОК\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["скульптор : статуя", "художник : мольберт", "зритель : выставка", "режиссёр : актёр"], "correctIndex": 0, "explanation": "Отношение «профессия — результат труда»: фотограф делает снимки, скульптор создаёт статуи. Художник : мольберт — профессия и инструмент."}, {"type": "analogy", "topic": "результат — профессия", "question": "МЕБЕЛЬ : СТОЛЯР\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["повар : суп", "часы : часовщик", "пациент : врач", "шкаф : комната"], "correctIndex": 1, "explanation": "Отношение «изделие — мастер»: мебель делает столяр, часы — часовщик. В паре «повар : суп» порядок обратный."}, {"type": "analogy", "topic": "вид — род", "question": "ДУБ : ДЕРЕВО\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["птица : ворона", "лист : дерево", "ворона : птица", "жёлудь : дуб"], "correctIndex": 2, "explanation": "Отношение «вид — род»: дуб — вид дерева, ворона — вид птицы. В паре «птица : ворона» порядок обратный, «лист : дерево» — часть и целое."}, {"type": "analogy", "topic": "род — вид", "question": "ПОСУДА : ТАРЕЛКА\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["стол : ножка", "тарелка : суп", "чашка : посуда", "инструмент : молоток"], "correctIndex": 3, "explanation": "Отношение «род — вид»: тарелка — вид посуды, молоток — вид инструмента. В паре «чашка : посуда» порядок обратный."}, {"type": "analogy", "topic": "материал — изделие", "question": "ШЕРСТЬ : СВИТЕР\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["кожа : ремень", "овца : шерсть", "свитер : шапка", "нитка : иголка"], "correctIndex": 0, "explanation": "Отношение «материал — изделие»: свитер вяжут из шерсти, ремень делают из кожи. Овца : шерсть — животное и то, что от него получают."}, {"type": "analogy", "topic": "изделие — материал", "question": "ВАЗА : ФАРФОР\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["стекло : бутылка", "кирпич : глина", "ваза : цветы", "фарфор : хрупкость"], "correctIndex": 1, "explanation": "Отношение «изделие — материал»: ваза из фарфора, кирпич из глины. В паре «стекло : бутылка» порядок обратный."}, {"type": "analogy", "topic": "предмет — функция", "question": "ХОЛОДИЛЬНИК : ОХЛАЖДЕНИЕ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["холодильник : кухня", "продукты : полка", "обогреватель : нагрев", "лёд : вода"], "correctIndex": 2, "explanation": "Отношение «прибор — его назначение»: холодильник служит для охлаждения, обогреватель — для нагрева."}, {"type": "analogy", "topic": "последовательность", "question": "ПОНЕДЕЛЬНИК : ВТОРНИК\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["март : весна", "декабрь : ноябрь", "суббота : выходной", "январь : февраль"], "correctIndex": 3, "explanation": "Второе слово непосредственно следует за первым: после понедельника — вторник, после января — февраль. В паре «декабрь : ноябрь» порядок обратный."}, {"type": "analogy", "topic": "этап — итог", "question": "ЧЕРНОВИК : ЧИСТОВИК\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["репетиция : спектакль", "премьера : репетиция", "актёр : сцена", "тетрадь : ручка"], "correctIndex": 0, "explanation": "Подготовительный этап и окончательный результат: сначала черновик, затем чистовик; сначала репетиция, затем спектакль. В паре «премьера : репетиция» порядок обратный."}, {"type": "analogy", "topic": "место — объект", "question": "АЭРОДРОМ : САМОЛЁТ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["самолёт : пилот", "порт : корабль", "автобус : пассажир", "самолёт : крыло"], "correctIndex": 1, "explanation": "Отношение «место стоянки — транспорт»: на аэродроме стоят и принимают самолёты, в порту — корабли."}, {"type": "analogy", "topic": "животное — детёныш", "question": "КОРОВА : ТЕЛЁНОК\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["телёнок : бык", "корова : молоко", "лошадь : жеребёнок", "овца : стадо"], "correctIndex": 2, "explanation": "Отношение «взрослое животное — его детёныш»: у коровы телёнок, у лошади жеребёнок."}, {"type": "analogy", "topic": "член — коллектив", "question": "МУЗЫКАНТ : ОРКЕСТР\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["скрипка : струна", "дирижёр : палочка", "оркестр : симфония", "футболист : команда"], "correctIndex": 3, "explanation": "Отношение «участник — коллектив»: музыкант входит в оркестр, футболист — в команду."}, {"type": "analogy", "topic": "предмет — характерный признак", "question": "САХАР : СЛАДКИЙ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["лимон : кислый", "соль : солонка", "горький : перец", "чай : сахар"], "correctIndex": 0, "explanation": "Предмет и его характерный вкус: сахар сладкий, лимон кислый. В паре «горький : перец» порядок обратный."}, {"type": "analogy", "topic": "действие — результат", "question": "РИСОВАТЬ : РИСУНОК\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["писать : ручка", "варить : суп", "читать : книга", "рисунок : художник"], "correctIndex": 1, "explanation": "Отношение «действие — его результат»: рисуя, создают рисунок; варя, получают суп. Книга не создаётся чтением — это объект действия."}, {"type": "analogy", "topic": "предмет — часть тела", "question": "ШЛЕМ : ГОЛОВА\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["шарф : зима", "ботинок : шнурок", "перчатка : рука", "кольчуга : металл"], "correctIndex": 2, "explanation": "Предмет надевают на часть тела, чтобы защитить её: шлем — на голову, перчатку — на руку."}, {"type": "analogy", "topic": "часть — целое", "question": "АТОМ : МОЛЕКУЛА\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["молекула : атом", "кислород : газ", "микроскоп : клетка", "клетка : ткань"], "correctIndex": 3, "explanation": "Структурная единица и то, что из неё состоит: молекулы состоят из атомов, ткани — из клеток. В паре «молекула : атом» порядок обратный."}, {"type": "analogy", "topic": "страна — столица", "question": "КЫРГЫЗСТАН : БИШКЕК\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["Узбекистан : Ташкент", "Токио : Япония", "Россия : Санкт-Петербург", "Ош : Кыргызстан"], "correctIndex": 0, "explanation": "Страна и её столица: столица Кыргызстана — Бишкек, Узбекистана — Ташкент. Санкт-Петербург не столица России, а в паре «Токио : Япония» порядок обратный."}, {"type": "analogy", "topic": "профессия — объект деятельности", "question": "ВЕТЕРИНАР : ЖИВОТНОЕ\n\nВыберите пару слов, отношения между которыми такие же, как в исходной паре.", "options": ["ветеринар : клиника", "педиатр : ребёнок", "садовник : лопата", "зоопарк : животное"], "correctIndex": 1, "explanation": "Врач и тот, кого он лечит: ветеринар лечит животных, педиатр — детей."}], "completions": [{"type": "completion", "question": "Несмотря на ___ погоду, экскурсия прошла ___.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["ненастную … успешно", "солнечную … прекрасно", "дождливую … отвратительно", "тёплую … весело"], "correctIndex": 0, "explanation": "«Несмотря на» требует противопоставления: плохая погода, но результат хороший."}, {"type": "completion", "question": "Учёный не спешил с выводами: он считал, что без ___ проверки любая гипотеза остаётся лишь ___.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["тщательной … предположением", "поверхностной … истиной", "тщательной … фактом", "быстрой … законом"], "correctIndex": 0, "explanation": "Без тщательной проверки гипотеза — всего лишь предположение, а не факт."}, {"type": "completion", "question": "Его речь была настолько ___, что слушатели с трудом улавливали главную мысль.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["путаной", "ясной", "краткой", "убедительной"], "correctIndex": 0, "explanation": "Трудно уловить мысль, если речь путаная."}, {"type": "completion", "question": "Старинный мост, который считали ___, простоял ещё полвека и оказался на удивление ___.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["ненадёжным … прочным", "крепким … прочным", "ненадёжным … хрупким", "новым … старым"], "correctIndex": 0, "explanation": "«На удивление» указывает на контраст: мост считали ненадёжным, а он оказался прочным."}, {"type": "completion", "question": "Экономист предупреждал, что резкий рост цен неизбежно приведёт к ___ спроса.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["снижению", "увеличению", "стабилизации", "ускорению"], "correctIndex": 0, "explanation": "Когда цены резко растут, люди покупают меньше — спрос снижается."}, {"type": "completion", "question": "Чем ___ человек, тем меньше он хвастается своими знаниями.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["образованнее", "невежественнее", "богаче", "моложе"], "correctIndex": 0, "explanation": "Смысл: по-настоящему образованные люди скромны в оценке своих знаний."}, {"type": "completion", "question": "Художник стремился не к точному ___ натуры, а к передаче своего ___ от увиденного.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["копированию … впечатления", "изучению … знания", "копированию … равнодушия", "искажению … отвращения"], "correctIndex": 0, "explanation": "Противопоставление «не точное копирование, а передача впечатления»."}, {"type": "completion", "question": "Лекарство подействовало не сразу, а ___: улучшение наступало медленно, день за днём.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["постепенно", "мгновенно", "внезапно", "случайно"], "correctIndex": 0, "explanation": "«Медленно, день за днём» — значит постепенно."}, {"type": "completion", "question": "Одни критики восхищались романом, другие же отзывались о нём крайне ___.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["неодобрительно", "восторженно", "благосклонно", "одобрительно"], "correctIndex": 0, "explanation": "«Одни … другие же» — противопоставление: восхищению противопоставлено неодобрение."}, {"type": "completion", "question": "Путешественник был ___ и потому взял с собой запас воды ещё на три дня.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["предусмотрителен", "беспечен", "рассеян", "ленив"], "correctIndex": 0, "explanation": "Взять запас «на всякий случай» — признак предусмотрительности."}, {"type": "completion", "question": "Эта теория долго считалась ___, пока новые опыты не ___ её.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["бесспорной … опровергли", "бесспорной … подтвердили", "ошибочной … опровергли", "известной … приняли"], "correctIndex": 0, "explanation": "«Долго считалась…, пока не…» говорит о перемене: бесспорную теорию опровергли."}, {"type": "completion", "question": "Его ответ был ___: всего три слова, но в них заключалось главное.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["лаконичным", "многословным", "туманным", "ошибочным"], "correctIndex": 0, "explanation": "Лаконичный — краткий, но содержательный."}, {"type": "completion", "question": "Из-за ___ дождей уровень воды в реке ___ поднялся.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["проливных … резко", "редких … резко", "слабых … значительно", "кратких … сильно"], "correctIndex": 0, "explanation": "Сильный подъём воды вызывают проливные дожди."}, {"type": "completion", "question": "Спортсмен проиграл не из-за ___ соперника, а из-за собственной ___.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["силы … невнимательности", "слабости … силы", "силы … подготовленности", "слабости … удачи"], "correctIndex": 0, "explanation": "«Не из-за…, а из-за собственной…» — причиной поражения названа его собственная ошибка."}, {"type": "completion", "question": "Документ был составлен настолько ___, что его можно было толковать по-разному.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["двусмысленно", "чётко", "грамотно", "подробно"], "correctIndex": 0, "explanation": "Толковать по-разному можно двусмысленный текст."}, {"type": "completion", "question": "Вместо того чтобы ___ конфликт, его слова лишь ___ спор.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["погасить … разожгли", "разжечь … погасили", "погасить … прекратили", "начать … закончили"], "correctIndex": 0, "explanation": "«Вместо того чтобы» — ожидали одного (погасить), а вышло противоположное (разожгли)."}, {"type": "completion", "question": "Хотя задача казалась ___, решение оказалось очень простым.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["сложной", "лёгкой", "решённой", "интересной"], "correctIndex": 0, "explanation": "«Хотя» — уступка: казалась сложной, но решение простое."}, {"type": "completion", "question": "Благодаря ___ подготовке команда ___ заняла первое место.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["упорной … заслуженно", "слабой … заслуженно", "упорной … случайно", "небрежной … неожиданно"], "correctIndex": 0, "explanation": "«Благодаря» указывает на положительную причину: упорная подготовка — заслуженная победа."}, {"type": "completion", "question": "Он был человеком ___: никогда не менял своих решений под чужим давлением.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["принципиальным", "уступчивым", "нерешительным", "легкомысленным"], "correctIndex": 0, "explanation": "Не уступать давлению — черта принципиального человека."}, {"type": "completion", "question": "Первые результаты исследования были ___, поэтому учёные решили ___ эксперимент.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["противоречивыми … повторить", "однозначными … повторить", "убедительными … отменить", "случайными … опубликовать"], "correctIndex": 0, "explanation": "Противоречивые результаты требуют повторной проверки."}, {"type": "completion", "topic": "наука", "question": "Хотя опыт повторяли многократно, результаты оставались ___, и учёные так и не смогли сделать ___ вывод.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["согласованными … окончательный", "противоречивыми … окончательный", "противоречивыми … ошибочный", "точными … верный"], "correctIndex": 1, "explanation": "«Хотя» указывает на неожиданный итог: несмотря на многие повторы, результаты противоречивы, поэтому окончательного вывода нет."}, {"type": "completion", "topic": "природа", "question": "Благодаря ___ климату и ___ почвам в этой долине выращивают абрикосы и виноград.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["тёплому … бедным", "суровому … плодородным", "тёплому … плодородным", "холодному … истощённым"], "correctIndex": 2, "explanation": "«Благодаря» вводит благоприятные причины: теплолюбивые культуры растут при тёплом климате и плодородных почвах."}, {"type": "completion", "topic": "история", "question": "Учёные долго не могли ___ древнюю письменность, пока не нашли надпись, продублированную на языке, который был им уже ___.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["изучить … непонятен", "расшифровать … незнаком", "уничтожить … известен", "расшифровать … известен"], "correctIndex": 3, "explanation": "Перевод на уже известный язык помогает расшифровать неизвестную письменность — поэтому находка и стала поворотной."}, {"type": "completion", "topic": "общество", "question": "Закон приняли, чтобы ___ права потребителей, однако на практике он оказался ___: нарушения продолжались.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["защитить … неэффективным", "защитить … действенным", "нарушить … полезным", "расширить … строгим"], "correctIndex": 0, "explanation": "«Однако» противопоставляет цель и результат: закон должен был защищать, но оказался неэффективным, раз нарушения продолжались."}, {"type": "completion", "topic": "школьная жизнь", "question": "Ученик не просто выучил правило наизусть, а ___ его смысл, поэтому легко ___ его в новых задачах.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["забыл … применял", "понял … применял", "понял … путал", "исказил … использовал"], "correctIndex": 1, "explanation": "Конструкция «не просто…, а…» усиливает: он понял смысл правила и поэтому свободно применял его."}, {"type": "completion", "topic": "природа", "question": "Вместо того чтобы ___ на зиму на юг, некоторые птицы остаются и ___ холода благодаря густому оперению.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["улетать … страдают от", "улетать … боятся", "улетать … переносят", "улетать … не выдерживают"], "correctIndex": 2, "explanation": "Птицы не улетают, а остаются, и «благодаря» густому оперению они переносят холода."}, {"type": "completion", "topic": "наука", "question": "Металлы хорошо проводят тепло, поэтому металлическая ложка в горячем чае быстро ___, а деревянная остаётся ___.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["тускнеет … холодной", "остывает … горячей", "нагревается … горячей", "нагревается … прохладной"], "correctIndex": 3, "explanation": "Металл хорошо проводит тепло и быстро нагревается; дерево проводит тепло плохо, поэтому деревянная ложка остаётся прохладной."}, {"type": "completion", "topic": "история", "question": "Изобретение книгопечатания сделало книги более ___, благодаря чему грамотность начала быстро ___.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["доступными … распространяться", "дорогими … распространяться", "доступными … исчезать", "редкими … расти"], "correctIndex": 0, "explanation": "Печатные книги стали дешевле и доступнее, а это способствовало распространению грамотности."}, {"type": "completion", "topic": "общество", "question": "Мнения жителей разделились: одни ___ строительство нового парка, другие выступали ___ него.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["поддерживали … за", "поддерживали … против", "осуждали … против", "критиковали … против"], "correctIndex": 1, "explanation": "«Мнения разделились» и «одни…, другие…» требуют противоположных позиций: одни за, другие против."}, {"type": "completion", "topic": "школьная жизнь", "question": "Несмотря на ___ урока, ученики слушали учителя с неослабевающим ___.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["продолжительность … безразличием", "краткость … вниманием", "продолжительность … вниманием", "увлекательность … равнодушием"], "correctIndex": 2, "explanation": "«Несмотря на» требует противопоставления: урок долгий, а внимание не ослабевало."}, {"type": "completion", "topic": "природа", "question": "В пустыне днём воздух сильно ___, а ночью, из-за отсутствия облаков, быстро ___.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["увлажняется … высыхает", "охлаждается … нагревается", "нагревается … увлажняется", "нагревается … остывает"], "correctIndex": 3, "explanation": "Днём солнце сильно нагревает пустыню, а ночью без облаков тепло быстро уходит и воздух остывает."}, {"type": "completion", "topic": "наука", "question": "Вакцина не лечит уже начавшуюся болезнь, а ___ её, поэтому прививку делают ___.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["предупреждает … заранее", "ускоряет … заранее", "предупреждает … после заболевания", "усиливает … вовремя"], "correctIndex": 0, "explanation": "«Не лечит, а…» — вакцина предупреждает болезнь, поэтому её вводят заранее, до заражения."}, {"type": "completion", "topic": "общество", "question": "Хотя интернет сделал информацию общедоступной, он же затруднил умение ___ достоверные сведения от ___.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["отличать … проверенных", "отличать … ложных", "смешивать … ложных", "получать … новых"], "correctIndex": 1, "explanation": "«Хотя» противопоставляет плюс и минус: информации стало больше, но труднее отличать достоверное от ложного."}, {"type": "completion", "topic": "история", "question": "Великий шёлковый путь пришёл в ___, когда морская торговля стала ___ и безопаснее сухопутной.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["упадок … дороже", "расцвет … дешевле", "упадок … дешевле", "расцвет … опаснее"], "correctIndex": 2, "explanation": "Если морской путь дешевле и безопаснее, торговцы уходят с сухопутного — и он приходит в упадок."}, {"type": "completion", "topic": "школьная жизнь", "question": "Чтобы ___ ошибок на экзамене, она не торопилась и ___ проверяла каждый ответ.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["наделать … тщательно", "избежать … небрежно", "допустить … внимательно", "избежать … внимательно"], "correctIndex": 3, "explanation": "Цель — избежать ошибок, средство — не торопиться и внимательно проверять ответы."}, {"type": "completion", "topic": "природа", "question": "Вырубка лесов на склонах гор ___ почву: без корней деревьев её легко ___ дождевая вода.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["ослабляет … смывает", "укрепляет … смывает", "ослабляет … удерживает", "удобряет … питает"], "correctIndex": 0, "explanation": "Корни деревьев удерживают почву; без них она становится непрочной и её смывает дождём."}, {"type": "completion", "topic": "общество", "question": "Он предпочитал не ___ в споре, а выслушать собеседника и ___ его доводы.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["перебивать … игнорировать", "перебивать … обдумать", "слушать … отвергнуть", "молчать … высмеять"], "correctIndex": 1, "explanation": "Конструкция «не…, а…»: вместо того чтобы перебивать, он выслушивал собеседника и обдумывал его доводы."}, {"type": "completion", "topic": "наука", "question": "Луна не излучает собственный свет, а лишь ___ солнечный, поэтому её видимая форма зависит от ___ относительно Солнца и Земли.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["отражает … размера", "поглощает … положения", "отражает … положения", "излучает … температуры"], "correctIndex": 2, "explanation": "Луна светит отражённым солнечным светом, поэтому видимая освещённая часть (фаза) зависит от её положения относительно Солнца и Земли."}, {"type": "completion", "topic": "школьная жизнь", "question": "Вместо того чтобы ___ подготовку на последний день, он занимался понемногу каждый день и к экзамену пришёл ___.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["продолжать … неготовым", "откладывать … растерянным", "начинать … уставшим", "откладывать … уверенным"], "correctIndex": 3, "explanation": "«Вместо того чтобы» противопоставляет плохую привычку (откладывать) хорошей (заниматься регулярно), результат которой — уверенность."}, {"type": "completion", "topic": "общество", "question": "Реформу провели, не посоветовавшись с гражданами, поэтому она вызвала не ___, а ___.\n\nВыберите вариант, который лучше всего подходит по смыслу для заполнения пропусков.", "options": ["поддержку … протесты", "протесты … поддержку", "одобрение … восторг", "протесты … благодарность"], "correctIndex": 0, "explanation": "«Поэтому» указывает на следствие: решение без учёта мнения граждан вызвало не поддержку, а протесты."}]}, "reading": [{"id": "yurt", "title": "Дом, который можно унести с собой", "text": "(1) Юрта веками была главным жилищем кочевников Центральной Азии. Её устройство кажется простым, но в нём продумана каждая деталь. (2) Основу юрты составляют раздвижные решётчатые стены — кереге. Их расставляют по кругу и соединяют между собой. (3) Над решётками поднимаются длинные изогнутые жерди — уук. Нижними концами они опираются на кереге, а верхними сходятся к деревянному кругу — түндүк. (4) Түндүк служит одновременно окном и дымоходом: через него в юрту проникает дневной свет и выходит дым от очага. (5) Снаружи каркас покрывают войлоком. Летом войлок защищает от жары, зимой хорошо сохраняет тепло, поэтому в юрте удобно в любое время года.\n(6) Главное достоинство юрты — её подвижность. Опытная семья разбирает и собирает жилище за час-два, а все его части можно перевезти на нескольких вьючных животных. (7) Для кочевника, который несколько раз в год перегонял скот с зимних пастбищ на летние и обратно, это было жизненно важно.\n(8) Сегодня юрта перестала быть обычным жильём, но не утратила своего значения. Её ставят на праздниках и в местах отдыха, а изображение түндүка можно увидеть на государственном флаге Кыргызстана. (9) Так юрта из предмета быта превратилась в символ, который напоминает о единстве народа и о мудрости предков.", "questions": [{"type": "reading", "passageId": "yurt", "question": "Какова основная мысль текста?", "options": ["Юрта — продуманное жилище кочевников, ставшее национальным символом", "Юрта неудобна для жизни в холодное время года", "Сегодня большинство людей в Кыргызстане живут в юртах", "Кереге — самая важная часть любой юрты"], "correctIndex": 0, "explanation": "Текст рассказывает об устройстве и достоинствах юрты и о том, как она стала символом (предложения 1, 6, 9)."}, {"type": "reading", "passageId": "yurt", "question": "Какую роль, согласно тексту, выполняет түндүк?", "options": ["Пропускает свет и выводит дым", "Служит дверью в юрту", "Защищает от ветра и дождя", "Соединяет решётчатые стены между собой"], "correctIndex": 0, "explanation": "Предложение 4: түндүк — «одновременно окно и дымоход»."}, {"type": "reading", "passageId": "yurt", "question": "Почему подвижность юрты была «жизненно важна» для кочевника (предложение 7)?", "options": ["Он несколько раз в год перегонял скот на другие пастбища", "Он часто ездил в город на праздники", "Войлок быстро изнашивался и его нужно было менять", "Юрты разрушались от сильных ветров"], "correctIndex": 0, "explanation": "Предложение 7 прямо объясняет: кочевник перегонял скот с зимних пастбищ на летние и обратно."}, {"type": "reading", "passageId": "yurt", "question": "В каком значении употреблено слово «каркас» в предложении 5?", "options": ["Основа, на которую крепится покрытие", "Наружное покрытие юрты", "Украшение над входом", "Материал для утепления"], "correctIndex": 0, "explanation": "Каркас — это кереге и уук (предложения 2–3), которые «снаружи покрывают войлоком», т.е. основа конструкции."}, {"type": "reading", "passageId": "yurt", "question": "Какой вывод можно сделать из последнего абзаца?", "options": ["Юрта сохранила значение как часть национальной культуры", "Юрты скоро полностью исчезнут", "Юрту перестали ставить даже на праздниках", "Изображение юрты случайно попало на флаг"], "correctIndex": 0, "explanation": "Предложения 8–9: юрта «не утратила своего значения» и стала символом."}], "words": 193}, {"id": "paper", "title": "Как бумага изменила мир", "text": "(1) Сегодня бумага кажется самым обычным материалом, но когда-то её изобретение стало настоящим переворотом. (2) До её появления люди писали на глиняных табличках, пергаменте из кожи животных, бамбуковых дощечках и шёлке. (3) Все эти материалы были либо тяжёлыми и громоздкими, либо очень дорогими: на одну большую рукопись из пергамента уходили шкуры целого стада.\n(4) Изобретение бумаги связывают с Китаем. По традиции его приписывают придворному чиновнику Цай Луню, который около 105 года описал способ изготовления бумаги из коры деревьев, старых сетей и тряпья. (5) Сырьё размачивали, толкли в кашицу, а затем тонким слоем вычерпывали сеткой и высушивали. (6) Получался лёгкий, дешёвый и удобный материал.\n(7) Несколько веков китайцы держали секрет в тайне. Лишь позднее он распространился по Великому шёлковому пути на запад. (8) По распространённой версии, после Таласской битвы 751 года, произошедшей недалеко от территории современного Кыргызстана, пленные китайские мастера помогли наладить производство бумаги в Самарканде. (9) Историки спорят о деталях этой истории, но известно, что вскоре самаркандская бумага стала знаменитой.\n(10) Дешёвая бумага сделала книги доступнее, а знания — быстрее распространяемыми. (11) Без неё было бы невозможно и появление книгопечатания много веков спустя.", "questions": [{"type": "reading", "passageId": "paper", "question": "Какой материал для письма, согласно тексту, был очень дорогим?", "options": ["Пергамент", "Бамбуковые дощечки", "Глиняные таблички", "Бумага из коры"], "correctIndex": 0, "explanation": "Предложение 3: на одну большую рукопись из пергамента «уходили шкуры целого стада» — это очень дорого."}, {"type": "reading", "passageId": "paper", "question": "Из чего, по тексту, изготавливали первую бумагу?", "options": ["Из коры деревьев, старых сетей и тряпья", "Из шёлка и кожи животных", "Из глины и бамбука", "Из хлопка и шерсти"], "correctIndex": 0, "explanation": "Предложение 4 перечисляет сырьё: кора, старые сети, тряпьё."}, {"type": "reading", "passageId": "paper", "question": "Почему автор использует выражение «по распространённой версии» (предложение 8)?", "options": ["Чтобы показать, что это не до конца доказанный факт", "Чтобы подчеркнуть, что все историки согласны", "Чтобы указать, что событие выдумано", "Чтобы сообщить точную дату"], "correctIndex": 0, "explanation": "Следующее предложение говорит: «Историки спорят о деталях этой истории»."}, {"type": "reading", "passageId": "paper", "question": "Какое значение имеет слово «переворот» в предложении 1?", "options": ["Коренное, резкое изменение", "Поворот на другой бок", "Военный захват власти", "Переворачивание страницы"], "correctIndex": 0, "explanation": "В контексте речь идёт об изобретении, которое сильно изменило жизнь людей."}, {"type": "reading", "passageId": "paper", "question": "Какое утверждение соответствует тексту?", "options": ["Бумага сделала знания более доступными", "Бумагу изобрели в Самарканде", "Китайцы сразу поделились секретом с соседями", "Книгопечатание появилось раньше бумаги"], "correctIndex": 0, "explanation": "Предложение 10: бумага сделала книги доступнее. Остальные утверждения противоречат тексту (предложения 4, 7, 11)."}], "words": 183}, {"id": "homework", "title": "Два мнения: нужны ли домашние задания?", "text": "ТЕКСТ А\n(1) Домашнее задание нередко называют пережитком прошлого, но я уверен, что без него обучение неполноценно. (2) На уроке ученик лишь знакомится с новым материалом, а по-настоящему усваивает его, когда самостоятельно решает задачи. (3) Именно дома, без подсказки учителя, становится ясно, что понято, а что нет. (4) Кроме того, регулярная домашняя работа приучает к дисциплине и умению планировать время — качествам, которые пригодятся и в университете, и на работе.\n\nТЕКСТ Б\n(5) Автор предыдущего текста прав в том, что знания закрепляются самостоятельной работой. (6) Но беда в том, что домашних заданий часто слишком много. (7) Ученик, который после шести-семи уроков ещё три-четыре часа сидит над тетрадями, не успевает ни отдохнуть, ни заняться спортом, ни выспаться. (8) Уставший ребёнок учится хуже, и польза от заданий исчезает. (9) Поэтому вопрос не в том, отменять ли домашнюю работу, а в том, сколько её давать: лучше небольшое, но продуманное задание, чем гора упражнений.", "questions": [{"type": "reading", "passageId": "homework", "question": "Какова главная мысль текста А?", "options": ["Домашнее задание необходимо для полноценного обучения", "Домашние задания нужно отменить", "Учитель должен помогать ученику дома", "На уроке ученик усваивает материал полностью"], "correctIndex": 0, "explanation": "Предложение 1: «без него обучение неполноценно»."}, {"type": "reading", "passageId": "homework", "question": "Какой довод в пользу домашних заданий приводит автор текста А?", "options": ["Они приучают к дисциплине и планированию времени", "Они освобождают время для спорта", "Они заменяют уроки в школе", "Они помогают родителям лучше знать программу"], "correctIndex": 0, "explanation": "Предложение 4."}, {"type": "reading", "passageId": "homework", "question": "С чем автор текста Б СОГЛАСЕН в тексте А?", "options": ["Знания закрепляются самостоятельной работой", "Домашних заданий должно быть больше", "Домашние задания надо отменить", "Уставший ребёнок учится лучше"], "correctIndex": 0, "explanation": "Предложение 5: «Автор предыдущего текста прав в том, что знания закрепляются самостоятельной работой»."}, {"type": "reading", "passageId": "homework", "question": "Какую проблему видит автор текста Б?", "options": ["Слишком большой объём домашних заданий", "Отсутствие домашних заданий", "Слишком короткие уроки", "Недостаток учебников"], "correctIndex": 0, "explanation": "Предложения 6–7: заданий «часто слишком много»."}, {"type": "reading", "passageId": "homework", "question": "Чем точнее всего различаются позиции авторов?", "options": ["Первый защищает домашние задания, второй предлагает уменьшить их объём", "Первый против домашних заданий, второй — за", "Оба предлагают отменить домашние задания", "Оба считают, что заданий должно быть больше"], "correctIndex": 0, "explanation": "Второй автор не против заданий в принципе (предложение 9), он против их чрезмерного объёма."}], "words": 150}, {"id": "issyk-kul", "title": "Озеро, которое не замерзает", "text": "(1) Иссык-Куль — одно из крупнейших высокогорных озёр мира и главная природная жемчужина Кыргызстана. (2) Оно лежит на высоте около 1600 метров над уровнем моря между хребтами Кюнгей Ала-Тоо и Терскей Ала-Тоо, которые относятся к горной системе Тянь-Шаня. (3) В переводе с кыргызского название озера означает «горячее озеро». (4) На первый взгляд такое имя кажется странным: зимы в этих местах бывают морозными, а вокруг лежат заснеженные вершины.\n(5) Однако у названия есть объяснение: даже в самые сильные холода Иссык-Куль не замерзает. (6) Этому способствуют сразу несколько причин. (7) Во-первых, озеро очень глубокое, и огромная масса воды, прогревшаяся за лето, медленно отдаёт тепло в течение всей зимы. (8) Во-вторых, вода в Иссык-Куле слабосолёная, а солёная вода замерзает при более низкой температуре, чем пресная. (9) Соль накапливается здесь потому, что в озеро впадает множество рек и ручьёв, но ни одна река из него не вытекает. (10) Вода уходит только путём испарения, а растворённые в ней соли остаются.\n(11) Незамерзающее озеро смягчает климат побережья: зимой здесь теплее, а летом прохладнее, чем в соседних горных долинах. (12) Поэтому берега Иссык-Куля издавна привлекают людей, а сегодня стали главным местом летнего отдыха в стране.", "questions": [{"type": "reading", "passageId": "issyk-kul", "topic": "Основная мысль", "question": "Какова основная мысль текста об Иссык-Куле?", "options": ["Название Иссык-Куля не соответствует его природе, ведь зимы здесь морозные", "Иссык-Куль стал местом отдыха прежде всего благодаря большой высоте над уровнем моря", "Иссык-Куль — необычное высокогорное озеро, которое по ряду природных причин не замерзает зимой", "Реки Тянь-Шаня приносят в Иссык-Куль тёплую воду, поэтому он не замерзает"], "correctIndex": 2, "explanation": "Большая часть текста объясняет, почему озеро не замерзает (предложения 5–10), и как это влияет на жизнь побережья (предложения 11–12)."}, {"type": "reading", "passageId": "issyk-kul", "topic": "Детали текста", "question": "Почему, согласно тексту, вода в Иссык-Куле солёная?", "options": ["Когда-то озеро было частью древнего моря, и соль осталась с тех времён", "В озеро поступает вода из солёных подземных источников на дне", "Летом вода сильно прогревается, и соль поднимается со дна озера", "Из озера не вытекает ни одна река, а вода уходит только испарением"], "correctIndex": 3, "explanation": "Предложения 9–10: реки впадают, но не вытекают; вода испаряется, а соли остаются."}, {"type": "reading", "passageId": "issyk-kul", "topic": "Вывод из текста", "question": "Что, судя по логике текста, произошло бы, если бы из Иссык-Куля вытекала крупная река?", "options": ["Озеро стало бы глубже и сильнее прогревалось бы летом", "Вода в озере, скорее всего, была бы менее солёной", "Вода в озере совсем перестала бы испаряться", "Климат побережья стал бы ещё мягче, чем сейчас"], "correctIndex": 1, "explanation": "По предложениям 9–10 соль копится, потому что вода уходит лишь испарением; с вытекающей рекой соли уносились бы из озера."}, {"type": "reading", "passageId": "issyk-kul", "topic": "Позиция и приёмы автора", "question": "Зачем автор в предложении 4 упоминает морозные зимы и заснеженные вершины?", "options": ["Чтобы доказать, что зимой озеро всё-таки покрывается льдом у самых берегов", "Чтобы подчеркнуть, что название озера на первый взгляд кажется странным", "Чтобы объяснить, откуда в озере берётся солёная вода", "Чтобы показать, что отдыхать на озере можно только летом"], "correctIndex": 1, "explanation": "В предложении 4 прямо сказано, что имя «кажется странным», а предложение 5 снимает это противоречие."}, {"type": "reading", "passageId": "issyk-kul", "topic": "Детали текста", "question": "Как, согласно тексту, Иссык-Куль влияет на климат побережья?", "options": ["Делает и зиму, и лето жарче", "Делает зиму холоднее, а лето теплее", "Приносит на побережье частые снегопады", "Делает зиму теплее, а лето прохладнее"], "correctIndex": 3, "explanation": "Предложение 11: «зимой здесь теплее, а летом прохладнее, чем в соседних горных долинах»."}]}, {"id": "glaciers", "title": "Ледяные кладовые Тянь-Шаня", "text": "(1) Высоко в горах Тянь-Шаня лежат тысячи ледников. (2) Издалека они похожи на неподвижные белые реки, но на самом деле лёд медленно сползает вниз по склонам под действием собственной тяжести. (3) Ледник рождается там, где за год выпадает больше снега, чем успевает растаять. (4) Слой за слоем снег уплотняется, превращается в зернистый фирн, а затем — в плотный голубоватый лёд.\n(5) Ледники часто называют природными водонапорными башнями. (6) Зимой они накапливают влагу в виде снега и льда, а летом, в самую жаркую и сухую пору, постепенно отдают её рекам. (7) Именно поэтому многие горные реки Кыргызстана особенно полноводны в середине лета, когда в долинах почти не бывает дождей. (8) Талая вода орошает поля и сады, питает пастбища, вращает турбины гидроэлектростанций.\n(9) Сегодня учёные отмечают, что многие ледники Тянь-Шаня сокращаются: из-за потепления климата они тают быстрее, чем пополняются. (10) В первые годы это может даже увеличить количество воды в реках. (11) Но если ледник исчезнет совсем, река лишится летнего источника питания и может сильно обмелеть именно тогда, когда вода нужнее всего. (12) Поэтому наблюдение за ледниками — это не только научная задача, но и забота о будущем целых регионов.", "questions": [{"type": "reading", "passageId": "glaciers", "topic": "Основная мысль", "question": "Какая мысль главная в тексте о ледниках Тянь-Шаня?", "options": ["Ледники Тянь-Шаня быстро растут, потому что климат становится теплее", "Ледники важны для снабжения водой, и их сокращение угрожает будущему регионов", "Ледники образуются из дождевой воды, которая замерзает в горах зимой", "Горные реки Кыргызстана наиболее полноводны зимой, когда идёт снег"], "correctIndex": 1, "explanation": "Текст объясняет роль ледников как источника воды (предложения 5–8) и опасность их таяния (предложения 9–12)."}, {"type": "reading", "passageId": "glaciers", "topic": "Значение слова", "question": "Почему ледники названы «природными водонапорными башнями» (предложение 5)?", "options": ["Они имеют форму высоких башен и видны издалека", "Они сами вырабатывают электричество для горных сёл", "Они запасают воду и отдают её тогда, когда она особенно нужна", "Они не дают рекам разливаться во время весенних дождей"], "correctIndex": 2, "explanation": "Предложение 6 поясняет сравнение: зимой ледники накапливают влагу, а летом отдают её рекам."}, {"type": "reading", "passageId": "glaciers", "topic": "Детали текста", "question": "Что, согласно тексту, происходит со снегом, прежде чем он станет льдом ледника?", "options": ["Он тает днём и снова замерзает ночью", "Он смешивается с водой горных рек", "Он испаряется и оседает на склонах инеем", "Он уплотняется и превращается в зернистый фирн"], "correctIndex": 3, "explanation": "Предложение 4: снег уплотняется, превращается в фирн, а затем — в лёд."}, {"type": "reading", "passageId": "glaciers", "topic": "Вывод из текста", "question": "Почему, по мнению автора, полное исчезновение ледника особенно опасно?", "options": ["Весной в долинах начнутся сильные наводнения", "В горах навсегда прекратятся зимние снегопады", "Долины станут более дождливыми и холодными", "Река может обмелеть летом, когда вода нужнее всего"], "correctIndex": 3, "explanation": "Предложение 11: река лишится летнего питания и обмелеет «именно тогда, когда вода нужнее всего»."}, {"type": "reading", "passageId": "glaciers", "topic": "Вывод из текста", "question": "Как следует понимать предложение 10?", "options": ["Потепление навсегда сделает горные реки полноводнее", "В первые годы потепления ледники вовсе перестают таять", "Количество воды в реках никак не зависит от ледников", "Сначала таяние может временно увеличить сток рек"], "correctIndex": 3, "explanation": "Слова «в первые годы» и «даже» показывают временный эффект, а предложение 11 говорит, что потом воды станет меньше."}]}, {"id": "arslanbob", "title": "Лес, в котором растут орехи", "text": "(1) На юге Кыргызстана, на склонах Ферганского и Чаткальского хребтов, растут удивительные леса. (2) Главное дерево в них — грецкий орех, а рядом с ним встречаются дикие яблони, груши, алыча и другие плодовые деревья. (3) Самый известный из этих лесов находится у села Арсланбоб в Джалал-Абадской области. (4) Ореховые леса Кыргызстана считаются одними из крупнейших естественных массивов грецкого ореха в мире.\n(5) Слово «естественный» здесь очень важно. (6) Эти деревья никто не сажал рядами, как в саду: лес возник сам и существует уже много веков. (7) Поэтому учёные видят в нём живой генетический «банк». (8) Дикие плодовые деревья приспособились к местным условиям, и их свойства могут пригодиться селекционерам при выведении новых устойчивых сортов.\n(9) Для жителей окрестных сёл лес — источник жизни. (10) Осенью, когда поспевают орехи, в сбор урожая включаются целые семьи. (11) Однако лес уязвим: вырубка, чрезмерный выпас скота и неосторожное обращение с огнём мешают молодым деревьям подниматься на смену старым. (12) Если старые деревья будут погибать, а новые не вырастут, лес постепенно исчезнет. (13) Поэтому бережное отношение к ореховым лесам — дело не только учёных и лесников, но и каждого, кто приходит сюда.", "questions": [{"type": "reading", "passageId": "arslanbob", "topic": "Основная мысль", "question": "Что является основной мыслью текста об ореховых лесах?", "options": ["Ореховые леса Кыргызстана были посажены людьми много веков назад", "Главная угроза ореховому лесу — осенний сбор орехов местными семьями", "Арсланбоб — единственное место в мире, где растёт грецкий орех", "Ореховые леса Кыргызстана ценны для науки и людей, но нуждаются в защите"], "correctIndex": 3, "explanation": "Автор рассказывает о ценности лесов (предложения 4–10) и призывает беречь их (предложения 11–13)."}, {"type": "reading", "passageId": "arslanbob", "topic": "Значение слова", "question": "В каком значении слово «естественный» употреблено в тексте (предложения 4–6)?", "options": ["Простой, непринуждённый", "Понятный, само собой разумеющийся", "Возникший сам, без посадки человеком", "Не содержащий химических добавок"], "correctIndex": 2, "explanation": "Предложение 6 поясняет: деревья «никто не сажал», лес «возник сам»."}, {"type": "reading", "passageId": "arslanbob", "topic": "Позиция и приёмы автора", "question": "Почему автор берёт слово «банк» в кавычки (предложение 7)?", "options": ["Так называется научная организация, которая изучает этот лес", "Лес приносит жителям окрестных сёл большой денежный доход", "Автор дословно цитирует слова жителей села Арсланбоб", "Это переносное значение: лес хранит ценные свойства растений"], "correctIndex": 3, "explanation": "Предложение 8 объясняет: лес «хранит» свойства диких деревьев, полезные селекционерам, — это переносное значение слова."}, {"type": "reading", "passageId": "arslanbob", "topic": "Детали текста", "question": "Что, согласно тексту, мешает ореховому лесу обновляться?", "options": ["Осенний сбор орехов и диких яблок", "Вырубка, выпас скота и пожары", "Слишком мягкий и влажный климат", "Работа селекционеров"], "correctIndex": 1, "explanation": "Предложение 11 прямо перечисляет эти причины."}, {"type": "reading", "passageId": "arslanbob", "topic": "Вывод из текста", "question": "Какой вывод можно сделать из предложений 11–12?", "options": ["Лес может исчезнуть, даже если сейчас взрослые деревья ещё растут", "Старые деревья мешают расти молодым, поэтому их нужно вырубать", "Лес восстанавливается сам при любых условиях, без помощи людей", "Молодые деревья дают больше орехов, чем старые, поэтому они ценнее"], "correctIndex": 0, "explanation": "Если молодые деревья не вырастут на смену старым, лес «постепенно исчезнет» (предложение 12)."}]}, {"id": "manas", "title": "Эпос, который хранила память", "text": "(1) Эпос «Манас» — величайшее произведение кыргызского народного творчества. (2) Он рассказывает о богатыре Манасе, который объединил разрозненные кыргызские племена и защищал их от врагов. (3) Продолжение эпоса посвящено его сыну Семетею и внуку Сейтеку, поэтому вместе эти части часто называют трилогией.\n(4) Удивительно не только содержание, но и то, как эпос дошёл до наших дней. (5) Веками его не записывали, а передавали из уст в уста. (6) Исполнителей эпоса называют манасчы. (7) Они не заучивали текст наизусть слово в слово: опираясь на знание сюжета и традиционных образов, сказитель каждый раз заново создавал рассказ прямо перед слушателями. (8) Поэтому у разных манасчы существуют разные варианты эпоса. (9) Одним из самых прославленных сказителей XX века был Саякбай Каралаев, от которого записан вариант в сотни тысяч стихотворных строк. (10) По объёму «Манас» во много раз превосходит знаменитые древнегреческие поэмы «Илиаду» и «Одиссею».\n(11) Эпос — это не только история о подвигах. (12) В нём отражены быт кочевников, их обычаи, представления о чести, дружбе и долге перед народом. (13) Сегодня кыргызская эпическая трилогия внесена в список нематериального культурного наследия ЮНЕСКО, а искусство манасчы продолжают осваивать молодые исполнители.", "questions": [{"type": "reading", "passageId": "manas", "topic": "Детали текста", "question": "Как, согласно тексту, эпос «Манас» сохранялся на протяжении веков?", "options": ["Его переписывали в рукописные книги", "Его передавали устно, из уст в уста", "Его высекали надписями на камнях", "Его изучали по школьным учебникам"], "correctIndex": 1, "explanation": "Предложение 5: «Веками его не записывали, а передавали из уст в уста»."}, {"type": "reading", "passageId": "manas", "topic": "Вывод из текста", "question": "Почему у разных манасчы существуют разные варианты эпоса?", "options": ["Каждый сказитель заново создавал рассказ во время исполнения", "Сказители намеренно искажали текст, чтобы отличаться от соперников", "Ранние записи эпоса были утеряны, и его восстанавливали по памяти", "Каждый манасчы сочинял сюжет о новом, своём собственном герое"], "correctIndex": 0, "explanation": "Предложения 7–8: сказитель не заучивал текст слово в слово, а создавал его заново, «поэтому» варианты различаются."}, {"type": "reading", "passageId": "manas", "topic": "Значение слова", "question": "Что означает слово «разрозненные» в предложении 2?", "options": ["Разобщённые, не связанные между собой", "Многочисленные, большие по численности", "Враждебные ко всем соседям", "Кочующие с места на место"], "correctIndex": 0, "explanation": "Манас «объединил» племена — значит, до этого они были разобщены; слово «разрозненные» противопоставлено объединению."}, {"type": "reading", "passageId": "manas", "topic": "Позиция и приёмы автора", "question": "С какой целью автор сравнивает «Манас» с «Илиадой» и «Одиссеей» (предложение 10)?", "options": ["Чтобы показать сходство сюжетов трёх произведений", "Чтобы подчеркнуть, что греческие поэмы древнее", "Чтобы показать огромный объём кыргызского эпоса", "Чтобы доказать, что «Манас» переведён с греческого"], "correctIndex": 2, "explanation": "В предложении 10 сравнение идёт именно «по объёму»: «Манас» во много раз превосходит греческие поэмы."}, {"type": "reading", "passageId": "manas", "topic": "Детали текста", "question": "Какое утверждение соответствует тексту?", "options": ["Манасчы заучивали эпос наизусть слово в слово", "Семетей — отец Манаса", "Эпос отражает обычаи и ценности кочевников", "Искусство манасчы сегодня полностью утрачено"], "correctIndex": 2, "explanation": "Предложение 12 говорит об обычаях и представлениях кочевников; остальные утверждения противоречат предложениям 3, 7 и 13."}]}, {"id": "blue-sky", "title": "Почему небо голубое", "text": "(1) Почему небо голубое? Этот вопрос задают дети, но полный ответ на него учёные нашли лишь в XIX веке. (2) Солнечный свет кажется белым, однако на самом деле он состоит из смеси лучей разных цветов — от красного до фиолетового. (3) В этом легко убедиться, глядя на радугу или на свет, прошедший через стеклянную призму.\n(4) На пути к земле солнечные лучи проходят через атмосферу и сталкиваются с молекулами воздуха. (5) Молекулы рассеивают свет, то есть отклоняют его в разные стороны. (6) Но рассеиваются лучи неодинаково: коротковолновый синий свет рассеивается гораздо сильнее, чем длинноволновый красный. (7) Рассеянный синий свет приходит к нам со всех сторон небосвода, поэтому небо и кажется голубым. (8) Фиолетовые лучи рассеиваются ещё сильнее, но в солнечном свете их меньше, а наш глаз к ним менее чувствителен.\n(9) Та же причина объясняет цвет заката. (10) Когда солнце стоит низко над горизонтом, его лучам приходится проходить сквозь гораздо более толстый слой воздуха. (11) По дороге почти весь синий свет рассеивается в стороны, и до наблюдателя доходят в основном жёлтые, оранжевые и красные лучи. (12) А вот на Луне, где атмосферы практически нет, небо остаётся чёрным даже днём.", "questions": [{"type": "reading", "passageId": "blue-sky", "topic": "Основная мысль", "question": "Какое утверждение точнее всего передаёт основную мысль текста о цвете неба?", "options": ["Солнечный свет на самом деле голубой, а белым он только кажется", "Цвет неба и заката объясняется рассеянием солнечного света в атмосфере", "Небо голубое, потому что в нём отражается цвет морей и океанов", "Закат красный, потому что солнце к вечеру остывает и тускнеет"], "correctIndex": 1, "explanation": "Предложения 5–7 объясняют голубой цвет неба рассеянием, а предложение 9 говорит, что «та же причина» объясняет цвет заката."}, {"type": "reading", "passageId": "blue-sky", "topic": "Детали текста", "question": "Какие лучи, согласно тексту, рассеиваются молекулами воздуха сильнее всего?", "options": ["Синие", "Красные", "Фиолетовые", "Жёлтые"], "correctIndex": 2, "explanation": "Предложение 8: фиолетовые лучи рассеиваются «ещё сильнее», чем синие, но небо не кажется фиолетовым, потому что их меньше и глаз к ним менее чувствителен."}, {"type": "reading", "passageId": "blue-sky", "topic": "Значение слова", "question": "Что означает глагол «рассеивают» в предложении 5?", "options": ["Отклоняют свет в разные стороны", "Полностью поглощают солнечный свет", "Усиливают яркость солнечных лучей", "Окрашивают свет в синий цвет"], "correctIndex": 0, "explanation": "Автор сам поясняет значение слова в предложении 5: «то есть отклоняют его в разные стороны»."}, {"type": "reading", "passageId": "blue-sky", "topic": "Вывод из текста", "question": "Почему, исходя из текста, на Луне небо чёрное даже днём?", "options": ["Там почти нет воздуха, который рассеивал бы солнечный свет", "Луна находится слишком далеко от Солнца и получает мало света", "Солнечный свет на Луне состоит только из красных лучей", "На Луне почти всё время длится ночь"], "correctIndex": 0, "explanation": "Голубой цвет неба создают молекулы воздуха (предложения 5–7), а на Луне «атмосферы практически нет» (предложение 12)."}, {"type": "reading", "passageId": "blue-sky", "topic": "Детали текста", "question": "Почему закат окрашен в жёлтые, оранжевые и красные тона?", "options": ["К вечеру молекулы воздуха сильно нагреваются и краснеют", "Вечером солнце начинает испускать только красный свет", "Красные лучи рассеиваются в воздухе сильнее, чем синие", "Лучи идут через толстый слой воздуха и теряют синий свет"], "correctIndex": 3, "explanation": "Предложения 10–11: у горизонта лучи проходят толстый слой воздуха, синий свет рассеивается, до нас доходят тёплые цвета."}]}, {"id": "autumn-leaves", "title": "Секрет осенних листьев", "text": "(1) Каждую осень деревья меняют зелёный наряд на жёлтый, оранжевый и багряный. (2) Многим кажется, что листья в это время окрашиваются в новые цвета. (3) На самом деле всё не совсем так.\n(4) Зелёный цвет листьям придаёт хлорофилл — пигмент, с помощью которого растение улавливает солнечный свет и создаёт питательные вещества. (5) Летом хлорофилла в листе очень много, и он маскирует другие пигменты. (6) Среди них — жёлтые и оранжевые каротиноиды, те же вещества, что окрашивают морковь. (7) Осенью дни становятся короче, становится холоднее, и дерево готовится сбросить листву. (8) Хлорофилл разрушается, а ценные вещества из листьев дерево переносит в ветви и корни, чтобы использовать весной. (9) Когда зелёный пигмент исчезает, становятся видны каротиноиды, которые всё лето находились в листе.\n(10) С красным цветом история другая. (11) Красные пигменты — антоцианы — у многих деревьев, например у клёнов, образуются в листьях именно осенью. (12) Их окраска бывает особенно яркой, если осенние дни солнечные, а ночи прохладные.\n(13) Так что жёлтая листва — это не новый наряд, а цвет, который до поры скрывался под зелёным.", "questions": [{"type": "reading", "passageId": "autumn-leaves", "topic": "Основная мысль", "question": "Какова основная мысль текста об осенних листьях?", "options": ["Осенью холод обжигает листья, и поэтому они меняют свой цвет", "Осенью хлорофилл постепенно превращается в жёлтые каротиноиды", "Все осенние пигменты появляются в листьях одновременно с холодами", "Осенняя окраска связана с исчезновением хлорофилла и другими пигментами"], "correctIndex": 3, "explanation": "Текст объясняет, что жёлтый цвет проявляется после разрушения хлорофилла (предложения 8–9), а красный дают антоцианы (предложение 11)."}, {"type": "reading", "passageId": "autumn-leaves", "topic": "Значение слова", "question": "Какое значение имеет слово «маскирует» в предложении 5?", "options": ["Уничтожает, полностью разрушает", "Усиливает, делает более яркими", "Скрывает, делает незаметными", "Создаёт, вырабатывает"], "correctIndex": 2, "explanation": "Каротиноиды есть в листе всё лето (предложение 9), но их не видно из-за хлорофилла — он их скрывает."}, {"type": "reading", "passageId": "autumn-leaves", "topic": "Детали текста", "question": "Чем, согласно тексту, жёлтые пигменты отличаются от красных?", "options": ["Жёлтые образуются только осенью, а красные появляются в листьях ещё весной", "Жёлтые находятся в листе всё лето, а красные у многих деревьев образуются осенью", "Жёлтые пигменты есть только в моркови, а красные — только в листьях клёнов", "Жёлтые пигменты разрушаются осенью, а красные — в середине лета"], "correctIndex": 1, "explanation": "Предложение 9: каротиноиды «всё лето находились в листе»; предложение 11: антоцианы образуются «именно осенью»."}, {"type": "reading", "passageId": "autumn-leaves", "topic": "Вывод из текста", "question": "Что можно предположить на основании предложения 12?", "options": ["В холодную осень листья клёнов так и останутся зелёными", "Солнечная погода разрушает в листьях красные пигменты", "В пасмурную и тёплую осень листья клёнов будут окрашены менее ярко", "Яркость осенней окраски листьев совсем не зависит от погоды"], "correctIndex": 2, "explanation": "Если яркая окраска бывает при солнечных днях и прохладных ночах, то при противоположной погоде она, вероятно, будет бледнее."}, {"type": "reading", "passageId": "autumn-leaves", "topic": "Позиция и приёмы автора", "question": "С какой целью автор упоминает морковь в предложении 6?", "options": ["Чтобы доказать, что морковь полезна для роста деревьев", "Чтобы показать, что листья и морковь растут одинаково", "Чтобы на знакомом примере пояснить, что такое каротиноиды", "Чтобы объяснить, откуда в листьях берётся хлорофилл"], "correctIndex": 2, "explanation": "Слово «каротиноиды» незнакомо многим читателям, и сравнение с морковью помогает представить их цвет."}]}, {"id": "moon-far-side", "title": "Невидимая сторона Луны", "text": "(1) Если внимательно смотреть на Луну в разные ночи, можно заметить, что тёмные пятна на её поверхности всегда расположены одинаково. (2) Это значит, что Луна всегда повёрнута к Земле одной и той же стороной.\n(3) Причина не в том, что Луна не вращается. (4) Она вращается вокруг своей оси, но делает один оборот ровно за то же время, за какое обходит вокруг Земли, — примерно за 27 суток. (5) Представьте, что вы идёте по кругу вокруг стола и всё время смотрите на него: вы сделаете и полный круг, и полный поворот вокруг себя, но стол ни разу не увидит вашу спину. (6) Такое совпадение не случайно: в далёком прошлом Луна вращалась быстрее, но притяжение Земли постепенно затормозило её вращение.\n(7) Обратную сторону Луны иногда называют «тёмной», но это ошибка. (8) Солнце освещает её так же, как и видимую сторону: когда на Земле наступает новолуние, обратная сторона как раз ярко освещена. (9) «Тёмной» её можно назвать лишь в переносном смысле — как неизвестную. (10) Впервые люди увидели её в 1959 году, когда советская станция «Луна-3» передала на Землю её фотографии. (11) Оказалось, что обратная сторона заметно отличается от видимой: на ней гораздо меньше тёмных равнин, так называемых морей.", "questions": [{"type": "reading", "passageId": "moon-far-side", "topic": "Детали текста", "question": "Почему, согласно тексту, с Земли всегда видна одна и та же сторона Луны?", "options": ["Луна делает оборот вокруг оси за то же время, за которое обходит Землю", "Луна совсем не вращается вокруг своей оси, а только движется по орбите", "Земля вращается вокруг оси так же медленно, как Луна", "Обратная сторона Луны слишком тёмная, чтобы её можно было увидеть"], "correctIndex": 0, "explanation": "Предложение 4: оборот вокруг оси занимает «ровно то же время», что и обращение вокруг Земли."}, {"type": "reading", "passageId": "moon-far-side", "topic": "Позиция и приёмы автора", "question": "Для чего автор приводит пример с прогулкой вокруг стола (предложение 5)?", "options": ["Чтобы наглядно объяснить сложное явление на бытовом примере", "Чтобы доказать, что на самом деле Луна не вращается", "Чтобы описать опыт, который провели астрономы", "Чтобы показать, как учёные измеряют период обращения Луны"], "correctIndex": 0, "explanation": "Пример со столом повторяет движение Луны: человек делает и круг, и поворот вокруг себя, оставаясь лицом к столу, — это облегчает понимание предложения 4."}, {"type": "reading", "passageId": "moon-far-side", "topic": "Детали текста", "question": "Какое утверждение ПРОТИВОРЕЧИТ тексту?", "options": ["Первые снимки обратной стороны Луны получены в 1959 году", "На обратной стороне Луны меньше «морей», чем на видимой", "В прошлом Луна вращалась быстрее, чем сейчас", "Обратная сторона Луны никогда не освещается Солнцем"], "correctIndex": 3, "explanation": "Предложение 8: Солнце освещает обратную сторону так же, как и видимую. Остальные утверждения совпадают с предложениями 6, 10 и 11."}, {"type": "reading", "passageId": "moon-far-side", "topic": "Значение слова", "question": "В каком смысле обратную сторону Луны можно назвать «тёмной» (предложение 9)?", "options": ["Как неосвещённую Солнцем", "Как неизвестную, неизученную", "Как покрытую тёмными морями", "Как очень холодную и безжизненную"], "correctIndex": 1, "explanation": "Предложение 9: «тёмной» её можно назвать «лишь в переносном смысле — как неизвестную»."}, {"type": "reading", "passageId": "moon-far-side", "topic": "Вывод из текста", "question": "Какой вывод можно сделать из предложения 8?", "options": ["В новолуние Солнце одинаково ярко освещает обе стороны Луны — и видимую, и обратную", "Во время новолуния видимая с Земли сторона Луны почти не освещена Солнцем", "Обратная сторона Луны бывает освещена только в полнолуние", "Новолуние случается очень редко, раз в несколько лет"], "correctIndex": 1, "explanation": "Если в новолуние ярко освещена обратная сторона, значит, сторона, обращённая к Земле, в это время находится в тени — поэтому Луну и не видно."}]}, {"id": "stethoscope", "title": "Трубка, которая научилась слушать", "text": "(1) Сегодня трудно представить врача без стетоскопа, но двести с небольшим лет назад этого прибора не существовало. (2) Чтобы услышать, как бьётся сердце и дышат лёгкие, врач прикладывал ухо прямо к груди больного. (3) Такой способ был не только неудобным, но и не слишком точным.\n(4) В 1816 году французский врач Рене Лаэннек осматривал молодую пациентку. (5) Прикладывать ухо к её груди он счёл неловким и вспомнил детскую забаву: если приложить ухо к одному концу длинного бревна, слышно, как по другому концу царапают булавкой. (6) Лаэннек свернул из нескольких листов бумаги плотную трубку, приставил один её конец к груди пациентки, а к другому приложил ухо. (7) К его удивлению, сердце зазвучало громче и отчётливее, чем раньше.\n(8) Позже врач заменил бумагу деревянным цилиндром и назвал своё изобретение стетоскопом — от греческих слов «грудь» и «смотреть». (9) Несколько лет он внимательно сравнивал звуки, которые слышал у больных, с проявлениями их болезней. (10) Так простая трубка превратилась в инструмент, позволяющий по звукам распознавать болезни.\n(11) История Лаэннека показывает, что открытие рождается не только в лаборатории. (12) Иногда достаточно наблюдательности и умения связать знакомое явление с новой задачей.", "questions": [{"type": "reading", "passageId": "stethoscope", "topic": "Детали текста", "question": "Что, согласно тексту, подсказало Лаэннеку идею стетоскопа?", "options": ["Совет более опытного врача-коллеги", "Устройство духового музыкального инструмента", "Детская забава с бревном и булавкой", "Древнегреческая книга о лечении сердца"], "correctIndex": 2, "explanation": "Предложение 5: врач вспомнил, что через длинное бревно слышно царапанье булавки."}, {"type": "reading", "passageId": "stethoscope", "topic": "Детали текста", "question": "Почему Лаэннек не стал прикладывать ухо к груди пациентки?", "options": ["Пациентка была тяжело больна", "Он плохо слышал", "Так запрещали правила больницы", "Он счёл это неловким"], "correctIndex": 3, "explanation": "Предложение 5: «Прикладывать ухо к её груди он счёл неловким»."}, {"type": "reading", "passageId": "stethoscope", "topic": "Значение слова", "question": "Что означает слово «отчётливее» в предложении 7?", "options": ["Быстрее и прерывистее", "Яснее, различимее", "Тише, приглушённее", "Чаще, с меньшими паузами"], "correctIndex": 1, "explanation": "Сердце через трубку стало слышно лучше: звук стал громче и яснее, его легче было различить."}, {"type": "reading", "passageId": "stethoscope", "topic": "Позиция и приёмы автора", "question": "Какую мысль автор выражает в последнем абзаце?", "options": ["Настоящие открытия делаются только в хорошо оснащённых лабораториях", "Детские игры для науки важнее, чем серьёзная научная работа", "Бумажные медицинские приборы надёжнее деревянных", "Открытия могут рождаться из наблюдательности и связи знакомого с новым"], "correctIndex": 3, "explanation": "Предложения 11–12: открытие рождается «не только в лаборатории», иногда достаточно наблюдательности."}, {"type": "reading", "passageId": "stethoscope", "topic": "Вывод из текста", "question": "Благодаря чему, судя по предложениям 9–10, стетоскоп стал инструментом для распознавания болезней?", "options": ["Лаэннек дал прибору звучное название от греческих слов «грудь» и «смотреть»", "Лаэннек годами сопоставлял услышанные звуки с проявлениями болезней", "Лаэннек свернул трубку из нескольких листов плотной бумаги", "Лаэннек осматривал в основном молодых пациентов"], "correctIndex": 1, "explanation": "Слово «так» в предложении 10 отсылает к предложению 9: именно многолетнее сравнение звуков с болезнями сделало трубку инструментом диагностики."}]}, {"id": "satellite-navigation", "title": "Как телефон узнаёт, где вы находитесь", "text": "(1) Открыв карту на смартфоне, мы за несколько секунд видим на ней точку — своё местоположение. (2) За этой привычной функцией стоит сложная система спутниковой навигации. (3) Самая известная из них — американская GPS, но существуют и другие, например российская ГЛОНАСС и европейская Galileo.\n(4) На высоте около двадцати тысяч километров над Землёй летают десятки навигационных спутников. (5) Каждый из них постоянно передаёт сигнал, в котором сообщает, где он находится и в какой момент сигнал был отправлен. (6) Приёмник в телефоне ловит эти сигналы и сравнивает время отправки со временем получения. (7) Радиоволны распространяются с известной скоростью — скоростью света, поэтому по задержке сигнала можно вычислить расстояние до спутника. (8) Зная расстояния хотя бы до четырёх спутников, приёмник определяет своё положение.\n(9) Главное условие точности — очень точное время. (10) Свет проходит около трёхсот километров за одну тысячную долю секунды, поэтому даже крошечная ошибка часов превращается в большую ошибку на карте. (11) Вот почему на спутниках установлены атомные часы — одни из самых точных приборов, созданных человеком.\n(12) Интересно, что сам телефон ничего не сообщает спутникам: он только принимает их сигналы. (13) Поэтому спутники не «знают», сколько людей ими пользуется.", "questions": [{"type": "reading", "passageId": "satellite-navigation", "topic": "Основная мысль", "question": "Какая мысль главная в тексте о спутниковой навигации?", "options": ["Телефон сам постоянно передаёт спутникам точные сведения о своём положении", "GPS — единственная в мире система спутниковой навигации", "Положение определяется по времени, за которое доходят сигналы спутников", "Точность навигации зависит прежде всего от размера экрана"], "correctIndex": 2, "explanation": "Предложения 5–8 описывают главный принцип: по задержке сигналов вычисляются расстояния до спутников, а по ним — положение."}, {"type": "reading", "passageId": "satellite-navigation", "topic": "Детали текста", "question": "Сколько спутников, согласно тексту, как минимум нужно приёмнику, чтобы определить своё положение?", "options": ["Один", "Два", "Четыре", "Три"], "correctIndex": 2, "explanation": "Предложение 8: нужно знать расстояния «хотя бы до четырёх спутников»."}, {"type": "reading", "passageId": "satellite-navigation", "topic": "Вывод из текста", "question": "Почему на навигационных спутниках нужны атомные часы?", "options": ["Они показывают точное время владельцам смартфонов", "Они ускоряют движение радиоволн от спутника к Земле", "Они помогают спутникам не сталкиваться друг с другом на орбите", "Даже малая ошибка во времени приводит к большой ошибке в расстоянии"], "correctIndex": 3, "explanation": "Предложения 10–11: за тысячную долю секунды свет проходит около 300 км, поэтому часы должны быть очень точными."}, {"type": "reading", "passageId": "satellite-navigation", "topic": "Вывод из текста", "question": "Какой вывод следует из предложений 12–13?", "options": ["Для навигации телефону достаточно только принимать сигналы", "Спутники ведут точный учёт всех пользователей навигации", "Телефон не может принимать сигналы от спутников", "Спутники выключаются, если ими никто не пользуется"], "correctIndex": 0, "explanation": "Телефон «только принимает» сигналы (предложение 12), значит, для навигации ему достаточно приёма."}, {"type": "reading", "passageId": "satellite-navigation", "topic": "Значение слова", "question": "Что означает слово «задержка» в предложении 7?", "options": ["Время, прошедшее от отправки сигнала до его получения", "Временная остановка в работе навигационного спутника", "Помеха, которая искажает радиосигнал по пути", "Опоздание пользователя, ждущего сигнала"], "correctIndex": 0, "explanation": "Предложение 6 объясняет, что приёмник сравнивает время отправки со временем получения, — эта разница и есть задержка."}]}, {"id": "memory-learning", "title": "Как не забыть выученное", "text": "(1) Многие школьники готовятся к экзаменам одинаково: откладывают всё на последние дни, а потом часами перечитывают учебник. (2) Кажется, что материал усвоен, но через неделю от него почти ничего не остаётся. (3) Психологи давно изучают, почему так происходит.\n(4) Ещё в конце XIX века немецкий учёный Герман Эббингауз провёл необычный опыт на самом себе. (5) Он заучивал наборы бессмысленных слогов и проверял, сколько помнит через разные промежутки времени. (6) Оказалось, что больше всего информации забывается в первые часы и дни после заучивания, а затем забывание замедляется. (7) Эту зависимость назвали кривой забывания.\n(8) Из исследований памяти следует несколько полезных советов. (9) Во-первых, повторять материал выгоднее не много раз подряд, а несколько раз с перерывами, постепенно увеличивая промежутки. (10) Такое распределённое повторение помогает удерживать знания гораздо дольше. (11) Во-вторых, полезно не просто перечитывать, а проверять себя: пересказывать текст своими словами, решать задачи, отвечать на вопросы. (12) Попытка вспомнить сама по себе укрепляет память. (13) Перечитывание же часто создаёт обманчивое чувство, будто всё уже знаешь: знакомый текст легко узнать, но это не значит, что его удастся воспроизвести.", "questions": [{"type": "reading", "passageId": "memory-learning", "topic": "Основная мысль", "question": "Какой совет составляет основную мысль текста о памяти?", "options": ["Готовиться к экзамену лучше всего в последние дни перед ним", "Знания лучше сохраняются при повторении с перерывами и самопроверке", "Бессмысленные слоги запоминаются лучше, чем осмысленный текст", "Любая информация забывается с одинаковой скоростью"], "correctIndex": 1, "explanation": "Главные советы текста — распределённое повторение и самопроверка (предложения 9–12)."}, {"type": "reading", "passageId": "memory-learning", "topic": "Детали текста", "question": "Что, согласно опыту Эббингауза, происходит с забыванием со временем?", "options": ["Сначала забывается мало, а потом всё больше и больше", "Забывание всё время идёт с одинаковой скоростью", "Сначала забывается много, потом забывание замедляется", "Через неделю забытое постепенно восстанавливается само"], "correctIndex": 2, "explanation": "Предложение 6: больше всего забывается в первые часы и дни, «а затем забывание замедляется»."}, {"type": "reading", "passageId": "memory-learning", "topic": "Значение слова", "question": "Какое значение имеет слово «обманчивое» в предложении 13?", "options": ["Создающее ложное впечатление", "Неприятное, вызывающее досаду", "Сильное, яркое", "Внезапное, неожиданное"], "correctIndex": 0, "explanation": "Чувство, «будто всё уже знаешь», не соответствует действительности: текст узнаёшь, но воспроизвести не можешь."}, {"type": "reading", "passageId": "memory-learning", "topic": "Вывод из текста", "question": "Какой способ подготовки лучше всего соответствует советам из текста?", "options": ["Повторять тему через день, три дня и неделю, пересказывая её", "Перечитать учебник пять раз подряд накануне экзамена", "Выучить всё за один день и больше к теме не возвращаться", "Внимательно читать учебник, не тратя время на задачи"], "correctIndex": 0, "explanation": "Этот способ сочетает повторение с увеличивающимися перерывами (предложение 9) и самопроверку (предложение 11)."}, {"type": "reading", "passageId": "memory-learning", "topic": "Позиция и приёмы автора", "question": "С какой целью автор рассказывает об опыте Эббингауза?", "options": ["Чтобы подробно рассказать о жизни немецкого учёного", "Чтобы убедить читателей учить бессмысленные слоги", "Чтобы научно обосновать советы о повторении", "Чтобы доказать, что память невозможно улучшить"], "correctIndex": 2, "explanation": "Опыт показывает, как быстро идёт забывание, а в предложении 8 автор выводит из исследований памяти практические советы."}]}, {"id": "opportunity-cost", "title": "Цена выбора", "text": "(1) В экономике есть понятие, которое помогает принимать решения в самых обычных ситуациях, — альтернативная стоимость. (2) Так называют ценность того лучшего варианта, от которого приходится отказаться, делая выбор.\n(3) Возьмём пример. (4) У Айбека свободен субботний вечер. (5) Он может пойти с друзьями в кино, а может три часа поработать в кафе у дяди и заработать немного денег. (6) Если Айбек выберет кино, его расходы составят не только цену билета. (7) Он также потеряет деньги, которые мог бы заработать за эти три часа. (8) Именно этот упущенный заработок и есть альтернативная стоимость похода в кино.\n(9) Альтернативная стоимость есть даже у того, что достаётся бесплатно. (10) Бесплатный концерт в парке не требует денег, но требует времени, а время можно было потратить иначе. (11) Поэтому экономисты любят повторять: «Бесплатных обедов не бывает».\n(12) Важно понимать, что альтернативная стоимость — это не повод отказываться от отдыха. (13) Иногда встреча с друзьями ценнее любого заработка. (14) Смысл в другом: делая выбор, полезно видеть не только то, что получаешь, но и то, чем за это платишь.", "questions": [{"type": "reading", "passageId": "opportunity-cost", "topic": "Значение слова", "question": "Что такое альтернативная стоимость, согласно тексту?", "options": ["Цена товара после того, как на него сделали скидку", "Ценность лучшего варианта, от которого отказались", "Сумма всех денежных расходов человека за день", "Стоимость самого дешёвого из возможных вариантов"], "correctIndex": 1, "explanation": "Определение дано в предложении 2."}, {"type": "reading", "passageId": "opportunity-cost", "topic": "Детали текста", "question": "Что будет альтернативной стоимостью похода в кино для Айбека?", "options": ["Цена купленного билета в кино", "Деньги, которые он мог бы заработать в кафе", "Время, которое он проведёт в кино вместе с друзьями", "Стоимость ужина в дядином кафе"], "correctIndex": 1, "explanation": "Предложение 8: альтернативная стоимость — это «упущенный заработок» за три часа работы."}, {"type": "reading", "passageId": "opportunity-cost", "topic": "Вывод из текста", "question": "Как в тексте следует понимать выражение «Бесплатных обедов не бывает» (предложение 11)?", "options": ["Обеды в кафе и ресторанах всегда обходятся слишком дорого", "За всё платят хотя бы временем или упущенными возможностями", "Проводить бесплатные концерты в городских парках невыгодно", "Экономисты считают, что отдыхать вредно для дела"], "correctIndex": 1, "explanation": "Предложение 10 поясняет: бесплатное всё равно требует времени, которое можно было потратить иначе."}, {"type": "reading", "passageId": "opportunity-cost", "topic": "Позиция и приёмы автора", "question": "Как автор относится к отдыху с друзьями?", "options": ["Считает, что он может быть ценнее заработка", "Считает его пустой тратой времени", "Советует отказаться от него ради работы", "Считает, что у него нет никакой цены"], "correctIndex": 0, "explanation": "Предложения 12–13: альтернативная стоимость «не повод отказываться от отдыха», встреча с друзьями бывает «ценнее любого заработка»."}, {"type": "reading", "passageId": "opportunity-cost", "topic": "Вывод из текста", "question": "Какой пример лучше всего иллюстрирует понятие, о котором идёт речь в тексте?", "options": ["Выбрав курсы английского, студентка не успевает в спортивную секцию", "Магазин снизил цену на хлеб, и покупателей у него стало заметно больше", "Зимой цены на овощи на рынке заметно выросли", "Покупатель заплатил за новый телефон наличными"], "correctIndex": 0, "explanation": "Отказ от секции ради курсов — это упущенный лучший вариант при выборе, то есть альтернативная стоимость (предложение 2)."}]}, {"id": "kok-boru", "title": "Игра, рождённая в степи", "text": "(1) Среди традиционных видов спорта кыргызов особое место занимает кок-бору. (2) Это стремительная конная игра, в которой две команды всадников борются за тушу козла — улак. (3) Цель — пронести её через поле и забросить в «казан» соперника: специальное возвышение, которое служит воротами.\n(4) Название игры переводится как «серый волк». (5) По одной из версий, игра выросла из старинного обычая: пастухи преследовали волков, нападавших на стада, и затем соревновались в ловкости, вырывая добычу друг у друга. (6) Так это или нет, ясно одно: кок-бору родилась из повседневной жизни кочевников, для которых конь был и транспортом, и помощником, и другом.\n(7) Со стороны игра может показаться грубой силовой схваткой. (8) Но успех в ней зависит прежде всего от мастерства. (9) Всаднику нужно на полном скаку наклониться и поднять с земли тяжёлую тушу, удержать её и не дать соперникам вырвать добычу. (10) Не менее важна слаженность команды: игроки прикрывают друг друга и передают улак, как мяч в регби. (11) А ещё многое зависит от коня: хорошо обученная лошадь чувствует всадника и смело идёт в борьбу.\n(12) Сегодня кок-бору — не просто забава на празднике. (13) Проводятся чемпионаты, а на Всемирных играх кочевников, которые впервые прошли в Кыргызстане в 2014 году, кок-бору стала одной из самых зрелищных дисциплин.", "questions": [{"type": "reading", "passageId": "kok-boru", "topic": "Основная мысль", "question": "Какова основная мысль текста о кок-бору?", "options": ["Кок-бору — грубая силовая схватка, в которой всё решает физическая сила", "Кок-бору придумали специально для Всемирных игр кочевников в 2014 году", "В кок-бору исход игры решает прежде всего скорость коня", "Кок-бору — традиционная конная игра, требующая мастерства и слаженности команды"], "correctIndex": 3, "explanation": "Автор рассказывает о происхождении игры и подчёркивает, что успех зависит от мастерства, командной игры и коня (предложения 8–11)."}, {"type": "reading", "passageId": "kok-boru", "topic": "Детали текста", "question": "Что в кок-бору называют «казаном»?", "options": ["Туша козла, за которую борются команды", "Возвышение, которое служит воротами", "Капитан команды всадников", "Котёл для праздничного угощения"], "correctIndex": 1, "explanation": "Предложение 3: «казан» — «специальное возвышение, которое служит воротами»."}, {"type": "reading", "passageId": "kok-boru", "topic": "Позиция и приёмы автора", "question": "Как автор относится к версии о происхождении игры от охоты на волков (предложения 5–6)?", "options": ["Считает её единственно верной и полностью доказанной", "Приводит её как возможную, но не настаивает на ней", "Полностью опровергает её с помощью фактов", "Называет её выдумкой, появившейся недавно"], "correctIndex": 1, "explanation": "Автор пишет «по одной из версий» и «так это или нет», то есть не настаивает на её точности."}, {"type": "reading", "passageId": "kok-boru", "topic": "Позиция и приёмы автора", "question": "С какой целью в предложении 10 игра сравнивается с регби?", "options": ["Чтобы показать, что игроки передают улак друг другу", "Чтобы доказать, что кок-бору произошла от регби", "Чтобы подчеркнуть, что в обеих играх нет лошадей", "Чтобы показать, что правила обеих игр полностью совпадают"], "correctIndex": 0, "explanation": "Сравнение касается только передачи улака между партнёрами по команде (предложение 10)."}, {"type": "reading", "passageId": "kok-boru", "topic": "Вывод из текста", "question": "Какой вывод можно сделать из предложений 7–9?", "options": ["Кок-бору слишком опасна, и её следует запретить", "В кок-бору побеждает самый тяжёлый всадник", "Первое впечатление об игре может быть обманчивым", "Всадники в кок-бору играют пешком"], "correctIndex": 2, "explanation": "Игра «может показаться» грубой схваткой (предложение 7), «но» на деле главное — мастерство (предложение 8)."}]}, {"id": "komuz-story", "title": "Первая мелодия", "text": "(1) Летом Бакыт гостил у деда на джайлоо. (2) Вечерами, когда овцы были загнаны, а над горами загорались первые звёзды, дед снимал со стены юрты комуз и садился у очага. (3) Три струны под его пальцами то стучали, как копыта скачущего коня, то шумели, как горный ручей, то затихали, словно ветер в траве.\n(4) — Чоң ата, научи меня, — попросил однажды Бакыт.\n(5) Дед молча протянул ему инструмент. (6) Бакыт уверенно ударил по струнам, но вместо музыки раздался нестройный звон. (7) Он попробовал ещё раз, потом ещё. (8) Пальцы не слушались, струны больно врезались в кожу.\n(9) — У комуза нет ладов, — сказал дед. — Где прижать струну, подскажет не дерево, а ухо. (10) Сначала научись слушать.\n(11) На следующий день Бакыт взял комуз с собой на пастбище. (12) Он сидел на камне и подолгу пытался повторить то, что слышал вокруг: цокот копыт, плеск воды, свист сурка. (13) Получалось плохо, но он не сдавался.\n(14) Через несколько недель вечером у очага Бакыт снова взял инструмент. (15) Мелодия была простой и неуверенной, в ней то и дело спотыкалась струна. (16) Но дед, слушая, улыбнулся и тихо сказал:\n(17) — Вот теперь ты играешь не только пальцами.", "questions": [{"type": "reading", "passageId": "komuz-story", "topic": "Основная мысль", "question": "Какова основная мысль рассказа?", "options": ["Чтобы научиться музыке, нужны терпение и умение слушать", "Играть на комузе можно научиться всего за один вечер", "Дед не хотел учить внука музыке и отказал ему", "Жизнь на джайлоо мешает всерьёз заниматься музыкой"], "correctIndex": 0, "explanation": "Бакыт добивается успеха, когда учится слушать мир вокруг и упорно занимается (предложения 10–14)."}, {"type": "reading", "passageId": "komuz-story", "topic": "Детали текста", "question": "Почему, по словам деда, играть на комузе нужно учиться «ухом» (предложение 9)?", "options": ["У комуза слишком много струн, и их трудно запомнить", "Дед сам не знал, куда правильно ставить пальцы", "У комуза нет ладов, подсказывающих, где прижать струну", "Комуз был старым и давно расстроенным"], "correctIndex": 2, "explanation": "Предложение 9: «У комуза нет ладов… подскажет не дерево, а ухо»."}, {"type": "reading", "passageId": "komuz-story", "topic": "Позиция и приёмы автора", "question": "Какой художественный приём автор использует в предложении 3?", "options": ["Спор между дедом и внуком о музыке", "Перечисление исторических сведений о кыргызском комузе", "Сравнение звуков комуза со звуками природы", "Обращение автора к читателю с вопросом"], "correctIndex": 2, "explanation": "Звуки струн сравниваются с копытами коня, горным ручьём и ветром в траве (слова «как», «словно»)."}, {"type": "reading", "passageId": "komuz-story", "topic": "Значение слова", "question": "Что означают слова «то и дело спотыкалась струна» в предложении 15?", "options": ["Струна порвалась прямо во время игры у очага", "Мелодия звучала с частыми запинками и ошибками", "Бакыт споткнулся о камень, когда нёс комуз", "Струна звучала слишком громко и резко, мешая деду"], "correctIndex": 1, "explanation": "Глагол «спотыкаться» употреблён в переносном значении: мелодия была «неуверенной», в ней случались сбои."}, {"type": "reading", "passageId": "komuz-story", "topic": "Вывод из текста", "question": "Как следует понимать последние слова деда (предложение 17)?", "options": ["Бакыт начал играть осмысленно, вкладывая в музыку услышанное", "Бакыт стал играть на комузе смычком, а не пальцами, как раньше", "Дед недоволен тем, что внук играет неправильно", "Бакыт уже играет на комузе лучше самого деда"], "correctIndex": 0, "explanation": "Дед улыбается (предложение 16): внук выполнил его совет «научись слушать» (предложение 10), и музыка идёт уже не только от пальцев, но и от слуха и души."}]}, {"id": "online-learning", "title": "Учиться дома или в классе?", "text": "ТЕКСТ А\n(1) Онлайн-обучение открывает возможности, о которых раньше нельзя было и мечтать. (2) Школьник из отдалённого села может слушать лекции лучших преподавателей страны и даже мира. (3) Урок в записи можно поставить на паузу, пересмотреть трудное место, вернуться к нему перед контрольной. (4) Каждый учится в своём темпе: сильный ученик идёт вперёд, а тот, кому нужно больше времени, спокойно разбирается в материале. (5) Я убеждён, что за таким обучением будущее, и школе стоит смелее его использовать.\n\nТЕКСТ Б\n(6) Спорить с тем, что онлайн-курсы делают знания доступнее, трудно. (7) Но у дистанционной учёбы есть слабое место: она требует от ученика огромной самодисциплины. (8) Дома рядом нет учителя, который заметит, что ты отвлёкся, и нет одноклассников, с которыми можно поспорить над задачей. (9) Многие начинают курс с воодушевлением, но бросают его на середине. (10) Кроме того, школа учит не только предметам: здесь подросток учится работать в команде, договариваться, отстаивать своё мнение. (11) Поэтому я считаю, что онлайн-занятия могут быть полезным дополнением к школе, но не её заменой.", "questions": [{"type": "reading", "passageId": "online-learning", "topic": "Основная мысль", "question": "Какова главная мысль текста А об онлайн-обучении?", "options": ["Онлайн-обучение подходит только самым сильным ученикам", "Онлайн-обучение даёт новые возможности, и за ним будущее", "Школы в отдалённых сёлах нужно закрыть за ненадобностью", "Уроки в записи хуже живых уроков с учителем"], "correctIndex": 1, "explanation": "Предложения 1 и 5: онлайн-обучение открывает новые возможности, «за таким обучением будущее»."}, {"type": "reading", "passageId": "online-learning", "topic": "Детали текста", "question": "Какой недостаток дистанционной учёбы называет автор текста Б?", "options": ["Она требует от ученика сильной самодисциплины", "Она обходится семьям школьников слишком дорого", "В интернете мало хороших преподавателей", "Записи уроков нельзя пересматривать"], "correctIndex": 0, "explanation": "Предложение 7: дистанционная учёба «требует от ученика огромной самодисциплины»."}, {"type": "reading", "passageId": "online-learning", "topic": "Сравнение текстов", "question": "В чём автор текста Б соглашается с автором текста А, сторонником онлайн-обучения?", "options": ["Онлайн-обучение должно заменить школу", "Ученику не нужен учитель", "Онлайн-курсы делают знания доступнее", "Дома легче сосредоточиться на учёбе"], "correctIndex": 2, "explanation": "Предложение 6: «Спорить с тем, что онлайн-курсы делают знания доступнее, трудно» — это перекликается с предложением 2 текста А."}, {"type": "reading", "passageId": "online-learning", "topic": "Значение слова", "question": "Какое значение имеет слово «воодушевление» в предложении 9?", "options": ["Растерянность, неуверенность", "Равнодушие, безразличие", "Душевный подъём, увлечённость", "Осторожность, опасливость"], "correctIndex": 2, "explanation": "Люди начинают курс с подъёмом, а потом бросают его — слово противопоставлено потере интереса."}, {"type": "reading", "passageId": "online-learning", "topic": "Сравнение текстов", "question": "Чем различаются взгляды авторов на онлайн-обучение?", "options": ["Автор А выступает против онлайн-обучения, а автор Б — за него", "Оба автора считают, что онлайн-обучение должно полностью заменить школу", "Оба автора считают онлайн-обучение бесполезным для школьников", "Автор А видит в онлайн-обучении будущее, автор Б — лишь дополнение к школе"], "correctIndex": 3, "explanation": "Сравните предложение 5 («за таким обучением будущее») и предложение 11 («дополнением к школе, но не её заменой»)."}]}, {"id": "phones-at-school", "title": "Смартфон на уроке", "text": "ТЕКСТ А\n(1) Во многих школах сегодня обсуждают, не запретить ли смартфоны на время занятий, и я поддерживаю такой запрет. (2) Телефон — источник постоянных отвлечений: уведомления, сообщения, игры. (3) Даже лёжа на парте экраном вниз, он напоминает о себе, и ученику трудно полностью сосредоточиться на уроке. (4) На переменах вместо того, чтобы поговорить или подвигаться, дети сидят, уткнувшись в экраны. (5) Если телефоны на время уроков будут лежать в шкафчике, школа станет местом, где учатся думать и общаться, а не пролистывать ленту.\n\nТЕКСТ Б\n(6) Запрет кажется простым решением, но, на мой взгляд, он борется со следствием, а не с причиной. (7) Смартфон — это инструмент, и всё зависит от того, как им пользоваться. (8) С его помощью можно за минуту найти значение незнакомого слова, пройти тест, посмотреть опыт, который нельзя провести в классе. (9) К тому же после школы телефон никто не отнимет, и если подростка не научили пользоваться им разумно, он так и не научится. (10) Гораздо полезнее договориться о правилах: когда телефон можно достать, а когда он должен лежать в сумке. (11) Учить нужно не жизни без гаджетов, а умению ими управлять.", "questions": [{"type": "reading", "passageId": "phones-at-school", "topic": "Детали текста", "question": "Какой довод в пользу запрета приводит автор текста А?", "options": ["Телефоны часто ломаются и теряются в школе", "Телефон мешает ученику сосредоточиться на уроке", "Родители не могут дозвониться детям во время уроков", "Смартфоны стоят слишком дорого для многих семей"], "correctIndex": 1, "explanation": "Предложения 2–3: телефон — «источник постоянных отвлечений», ученику «трудно полностью сосредоточиться»."}, {"type": "reading", "passageId": "phones-at-school", "topic": "Значение слова", "question": "Как следует понимать выражение «борется со следствием, а не с причиной» (предложение 6)?", "options": ["Запрет полностью и навсегда решает проблему", "Запрет направлен прежде всего против учителей", "Запрет вводится слишком поздно, когда уже ничего не изменить", "Запрет убирает проявление проблемы, но не решает её суть"], "correctIndex": 3, "explanation": "Автор Б считает, что суть проблемы — неумение разумно пользоваться телефоном (предложения 9, 11), а запрет лишь убирает телефон с глаз."}, {"type": "reading", "passageId": "phones-at-school", "topic": "Детали текста", "question": "Что предлагает автор текста Б вместо запрета?", "options": ["Разрешить телефоны без всяких ограничений", "Отбирать телефоны на весь учебный год", "Заменить все учебники смартфонами", "Договориться о правилах пользования телефоном"], "correctIndex": 3, "explanation": "Предложение 10: «Гораздо полезнее договориться о правилах»."}, {"type": "reading", "passageId": "phones-at-school", "topic": "Вывод из текста", "question": "Как автор текста Б, скорее всего, отнёсся бы к уроку, на котором ученики ищут в смартфонах значения незнакомых слов?", "options": ["Одобрил бы такое использование телефона", "Потребовал бы убрать телефоны в шкафчики", "Счёл бы это пустой тратой времени", "Предложил бы запретить смартфоны в школе"], "correctIndex": 0, "explanation": "В предложении 8 автор Б сам приводит поиск значения незнакомого слова как пример полезного использования смартфона."}, {"type": "reading", "passageId": "phones-at-school", "topic": "Сравнение текстов", "question": "В чём главное различие позиций авторов?", "options": ["Автор А предлагает разрешить телефоны, а автор Б — запретить их", "Оба автора выступают за полный запрет смартфонов в школе", "Оба автора считают, что телефоны никак не влияют на учёбу", "Автор А за запрет телефонов, автор Б — за умение ими пользоваться"], "correctIndex": 3, "explanation": "Предложение 1: автор А «поддерживает запрет»; предложение 11: автор Б хочет учить «умению ими управлять»."}]}, {"id": "mountain-tourism", "title": "Туризм в горах: выгода или угроза?", "text": "ТЕКСТ А\n(1) Горы Кыргызстана — настоящее богатство, и туризм помогает превратить его в благополучие для людей. (2) Когда в село приезжают путешественники, у местных жителей появляется работа: они сдают комнаты, водят группы по тропам, дают напрокат лошадей, продают домашнюю еду и изделия из войлока. (3) Молодёжи не нужно уезжать в город в поисках заработка. (4) Кроме того, гости знакомятся с культурой кочевников, а жители начинают больше ценить собственные традиции. (5) Поэтому туризм в горах нужно развивать: строить дороги и гостевые дома, прокладывать новые маршруты.\n\nТЕКСТ Б\n(6) Туризм действительно даёт горным сёлам доход, и я не призываю закрыть горы для гостей. (7) Но природа высокогорья очень хрупка. (8) Вытоптанный участок альпийского луга может восстанавливаться многие годы, а мусор, оставленный у озера, сам никуда не исчезнет. (9) Если туристов станет слишком много, они разрушат ту самую красоту, ради которой приезжают. (10) Поэтому развивать туризм нужно осторожно: ограничивать число посетителей на особенно ценных участках, прокладывать тропы так, чтобы люди не сходили с них, и приучать гостей уносить мусор с собой.", "questions": [{"type": "reading", "passageId": "mountain-tourism", "topic": "Основная мысль", "question": "Что утверждает автор текста А о туризме в горах?", "options": ["Туризм приносит пользу жителям гор, и его нужно развивать", "Туризм разрушает традиции и обычаи кочевников", "Молодёжи из горных сёл лучше уезжать в города", "Горы нужно закрыть для гостей, чтобы сберечь природу"], "correctIndex": 0, "explanation": "Предложения 1 и 5: туризм превращает богатство гор в благополучие людей, «поэтому туризм в горах нужно развивать»."}, {"type": "reading", "passageId": "mountain-tourism", "topic": "Детали текста", "question": "Какую пользу туризма для молодёжи называет автор текста А?", "options": ["Молодёжь может бесплатно путешествовать по горам", "Молодёжь быстрее учит иностранные языки у гостей", "Молодым людям не нужно уезжать в город ради заработка", "Молодым больше не нужно заниматься скотоводством"], "correctIndex": 2, "explanation": "Предложение 3: «Молодёжи не нужно уезжать в город в поисках заработка»."}, {"type": "reading", "passageId": "mountain-tourism", "topic": "Значение слова", "question": "В каком значении употреблено слово «хрупка» в предложении 7?", "options": ["Очень красива и привлекательна для гостей", "Сурова и опасна для человека", "Легко повреждается и медленно восстанавливается", "Мало изучена учёными"], "correctIndex": 2, "explanation": "Предложение 8 поясняет: вытоптанный луг восстанавливается «многие годы»."}, {"type": "reading", "passageId": "mountain-tourism", "topic": "Сравнение текстов", "question": "С каким утверждением согласились бы оба автора?", "options": ["Число туристов в горах нужно ограничивать повсюду", "Туризм даёт доход жителям горных сёл", "Туризм в горах нужно запретить", "Природа гор быстро восстанавливается сама"], "correctIndex": 1, "explanation": "Автор А говорит о работе для местных жителей (предложение 2), автор Б признаёт: туризм «действительно даёт горным сёлам доход» (предложение 6)."}, {"type": "reading", "passageId": "mountain-tourism", "topic": "Сравнение текстов", "question": "Чем различаются позиции авторов по вопросу о горном туризме?", "options": ["Автор А за активное развитие туризма, автор Б — за осторожное", "Автор А выступает против туризма, а автор Б — за него", "Автор Б предлагает полностью закрыть горы для туристов", "Оба автора считают, что туризм вредит культуре кочевников"], "correctIndex": 0, "explanation": "Автор Б не против туризма (предложение 6), но настаивает на осторожном развитии (предложение 10), тогда как автор А о рисках не говорит."}]}, {"id": "city-or-village", "title": "Где лучше жить: в городе или в селе?", "text": "ТЕКСТ А\n(1) Каждый год тысячи молодых людей переезжают из сёл в города, и понять их легко. (2) В городе есть университеты, библиотеки, больницы, театры, а главное — выбор. (3) Здесь можно найти работу по своей профессии, а не довольствоваться тем, что есть поблизости. (4) Город быстрее меняется и быстрее меняет человека: в нём проще встретить людей с похожими интересами, научиться новому, начать своё дело. (5) Для тех, кто хочет развиваться, город открывает больше дверей.\n\nТЕКСТ Б\n(6) Я вырос в селе и не променял бы его ни на какой мегаполис. (7) Да, в городе больше возможностей, этого я не отрицаю. (8) Но за них приходится платить шумом, пробками, дорогим жильём и вечной спешкой. (9) В селе люди знают друг друга, помогают соседям, а дети растут на свежем воздухе. (10) К тому же сегодня многое изменилось: благодаря интернету можно учиться и даже работать, не уезжая из дома. (11) Думаю, выбор зависит от того, что человек ценит больше: скорость и разнообразие или спокойствие и близость к людям и природе.", "questions": [{"type": "reading", "passageId": "city-or-village", "topic": "Основная мысль", "question": "Какова главная мысль текста А о жизни в городе?", "options": ["Жить в селе лучше, чем в городе", "Молодёжь переезжает в город только ради развлечений", "В городе трудно найти работу", "Город даёт больше возможностей для развития"], "correctIndex": 3, "explanation": "Предложение 5 подводит итог: «Для тех, кто хочет развиваться, город открывает больше дверей»."}, {"type": "reading", "passageId": "city-or-village", "topic": "Позиция и приёмы автора", "question": "Какое выражение автор текста А употребляет в переносном смысле?", "options": ["«открывает больше дверей»", "«переезжают из сёл в города»", "«найти работу по своей профессии»", "«есть университеты, библиотеки»"], "correctIndex": 0, "explanation": "В предложении 5 речь идёт не о настоящих дверях, а о возможностях, которые даёт город."}, {"type": "reading", "passageId": "city-or-village", "topic": "Сравнение текстов", "question": "С каким положением текста А соглашается автор текста Б, выросший в селе?", "options": ["В городе больше возможностей", "Жизнь в городе спокойнее", "В селе нельзя получить образование", "Жильё в городе дешевле"], "correctIndex": 0, "explanation": "Предложение 7: «Да, в городе больше возможностей, этого я не отрицаю»."}, {"type": "reading", "passageId": "city-or-village", "topic": "Детали текста", "question": "Какой довод приводит автор текста Б, чтобы показать, что жить в селе стало удобнее?", "options": ["В сёлах построили новые театры и университеты", "Жильё в сёлах стало дороже, чем в городах", "В сёлах стало больше людей с похожими интересами", "Интернет позволяет учиться и работать, не уезжая"], "correctIndex": 3, "explanation": "Предложение 10: «благодаря интернету можно учиться и даже работать, не уезжая из дома»."}, {"type": "reading", "passageId": "city-or-village", "topic": "Сравнение текстов", "question": "Какой вывод делает автор текста Б, в отличие от автора текста А?", "options": ["Всем, кто хочет развиваться, нужно переехать в город", "Жить в большом городе человеку просто невозможно", "Ради образования село необходимо покинуть навсегда", "Выбор места жизни зависит от того, что ценит сам человек"], "correctIndex": 3, "explanation": "Предложение 11: выбор «зависит от того, что человек ценит больше»; автор А же прямо связывает развитие с городом (предложение 5)."}]}], "grammar": [{"type": "grammar", "kind": "орфография", "question": "В каком слове на месте пропуска пишется буква Е?", "options": ["пр..красный", "пр..бежать", "пр..школьный", "пр..шить"], "correctIndex": 0, "explanation": "Прекрасный — приставка ПРЕ- в значении «очень». В остальных ПРИ-: прибежать (приближение), пришкольный (близость), пришить (присоединение)."}, {"type": "grammar", "kind": "орфография", "question": "В каком слове пишется НН?", "options": ["деревя..ый", "кожа..ый", "серебря..ый", "ю..ый"], "correctIndex": 0, "explanation": "Деревянный — слово-исключение (стеклянный, оловянный, деревянный). Кожаный, серебряный, юный пишутся с одной Н."}, {"type": "grammar", "kind": "орфография", "question": "В каком слове на конце пишется мягкий знак?", "options": ["ноч..", "плач..", "мяч..", "камыш.."], "correctIndex": 0, "explanation": "После шипящих Ь пишется у существительных женского рода 3-го склонения: ночь. Плач, мяч, камыш — мужской род, без Ь."}, {"type": "grammar", "kind": "орфография", "question": "Какое слово пишется с НЕ слитно?", "options": ["(не)навидеть", "(не)спеша", "(не)был", "(не)мой"], "correctIndex": 0, "explanation": "«Ненавидеть» без НЕ не употребляется — пишется слитно. С глаголами, деепричастиями и местоимениями (как здесь) НЕ пишется раздельно."}, {"type": "grammar", "kind": "орфография", "question": "В каком слове пропущена безударная гласная, проверяемая ударением?", "options": ["г..ра", "р..сток", "к..саться", "з..ря"], "correctIndex": 0, "explanation": "Гора — проверка: гóры. В остальных словах корни с чередованием (раст/рос, кас/кос, зар/зор), их по ударению не проверяют."}, {"type": "grammar", "kind": "орфография", "question": "В каком слове на месте пропуска пишется разделительный твёрдый знак (Ъ)?", "options": ["под..езд", "в..юга", "сем..я", "солов..и"], "correctIndex": 0, "explanation": "Ъ пишется после приставки на согласную перед Е, Ё, Ю, Я: подъезд. В остальных — разделительный Ь внутри корня/перед окончанием."}, {"type": "grammar", "kind": "пунктуация", "question": "В каком предложении перед союзом И нужна запятая?", "options": ["Солнце село(,) и стало прохладно.", "Мы читали(,) и писали до вечера.", "Он пел(,) и танцевал весь вечер.", "Дети смеялись(,) и шумели во дворе."], "correctIndex": 0, "explanation": "Здесь И соединяет две грамматические основы (солнце село; стало прохладно) — это сложное предложение, нужна запятая. В остальных И соединяет однородные сказуемые."}, {"type": "grammar", "kind": "пунктуация", "question": "В каком предложении есть обращение, которое нужно выделить запятой?", "options": ["Друзья(,) давайте встретимся завтра.", "Друзья пришли вовремя.", "Мы ждали друзей весь день.", "Друзьям понравился фильм."], "correctIndex": 0, "explanation": "«Друзья» здесь — обращение к собеседникам, оно выделяется запятыми. В остальных предложениях это подлежащее или дополнение."}, {"type": "grammar", "kind": "пунктуация", "question": "В каком предложении нужно поставить двоеточие?", "options": ["На столе лежали школьные принадлежности( ) книги, тетради и ручки.", "Книги, тетради и ручки лежали на столе.", "Я купил книги( ) потому что люблю читать.", "Он сказал( ) что придёт позже."], "correctIndex": 0, "explanation": "После обобщающего слова («принадлежности») перед однородными членами ставится двоеточие. В двух других случаях нужна запятая."}, {"type": "grammar", "kind": "пунктуация", "question": "В каком предложении нужно выделить оборот запятой?", "options": ["Закончив работу( ) он пошёл домой.", "Он работал не покладая рук.", "Он ответил не задумываясь.", "Мы шли по широкой дороге к реке."], "correctIndex": 0, "explanation": "Деепричастный оборот «закончив работу» выделяется запятой. «Не покладая рук» и «не задумываясь» — устойчивые выражения, запятыми не выделяются."}, {"type": "grammar", "kind": "пунктуация", "question": "В каком предложении нужна запятая?", "options": ["Я знаю( ) что ты прав.", "Я знаю тебя давно.", "Я знаю этот ответ.", "Я знаю о твоих успехах."], "correctIndex": 0, "explanation": "Это сложноподчинённое предложение: придаточное «что ты прав» отделяется запятой."}, {"type": "grammar", "kind": "пунктуация", "question": "В каком предложении есть вводное слово, которое нужно выделить запятыми?", "options": ["Он( ) конечно( ) прав.", "Это было очень давно.", "Мы пришли домой поздно вечером.", "Он всегда говорит правду."], "correctIndex": 0, "explanation": "«Конечно» — вводное слово, выражает уверенность говорящего, выделяется запятыми."}, {"type": "grammar", "kind": "словообразование", "question": "Какое слово образовано приставочным способом?", "options": ["перечитать", "читатель", "чтение", "читальня"], "correctIndex": 0, "explanation": "Пере- + читать → перечитать (добавлена только приставка). Остальные образованы с помощью суффиксов."}, {"type": "grammar", "kind": "словообразование", "question": "Какое слово образовано сложением основ?", "options": ["пароход", "походка", "подводный", "дорожка"], "correctIndex": 0, "explanation": "Пароход = пар + о + ход: соединены две основы."}, {"type": "grammar", "kind": "словообразование", "question": "С помощью какой морфемы образовано слово «учитель» от глагола «учить»?", "options": ["суффикса -тель", "приставки у-", "суффикса -и-", "окончания -ь"], "correctIndex": 0, "explanation": "Уч(ить) + -тель → учитель: суффикс -тель обозначает того, кто совершает действие."}, {"type": "grammar", "kind": "словообразование", "question": "В каком ряду все слова однокоренные?", "options": ["вода, водный, подводник", "вода, водитель, водичка", "гора, горе, горный", "лес, лестница, лесник"], "correctIndex": 0, "explanation": "Общий корень -вод- со значением «вода». «Водитель» (от «водить»), «горе», «лестница» — слова с другими корнями, лишь похожими по звучанию."}, {"type": "grammar", "kind": "словообразование", "question": "Какое слово образовано приставочно-суффиксальным способом?", "options": ["подоконник", "окошко", "оконный", "окна"], "correctIndex": 0, "explanation": "Под- + окон + -ник: слово образовано от «окно» одновременным добавлением приставки и суффикса."}, {"type": "grammar", "kind": "словообразование", "question": "Какое слово состоит из приставки, корня, суффикса и окончания?", "options": ["пригородный", "рассказ", "лесной", "переход"], "correctIndex": 0, "explanation": "При- (приставка) + город (корень) + -н- (суффикс) + -ый (окончание). В «рассказ» и «переход» нет суффикса, в «лесной» — приставки."}, {"type": "grammar", "kind": "дополнение", "question": "Выберите правильную форму: «В шкафу нет чистых ___».", "options": ["носков", "носок", "носка", "носках"], "correctIndex": 0, "explanation": "Норма: пара носков (но: пара чулок, сапог)."}, {"type": "grammar", "kind": "дополнение", "question": "Выберите правильную форму: «Согласно ___ директора занятия отменены».", "options": ["приказу", "приказа", "приказом", "приказе"], "correctIndex": 0, "explanation": "Предлог «согласно» требует дательного падежа: согласно чему? — приказу."}, {"type": "grammar", "kind": "дополнение", "question": "Выберите правильное слово: «На улице холодно, ___ тёплое пальто».", "options": ["надень", "одень", "оденься", "наденься"], "correctIndex": 0, "explanation": "Надеть — что-то на себя (пальто, шапку); одеть — кого-то (одеть ребёнка)."}, {"type": "grammar", "kind": "дополнение", "question": "Выберите правильный вариант: «___ в город мы сразу позвонили родителям».", "options": ["По приезде", "По приезду", "По приездом", "По приездах"], "correctIndex": 0, "explanation": "Предлог «по» в значении «после» требует предложного падежа: по приезде, по окончании, по возвращении."}, {"type": "grammar", "kind": "дополнение", "question": "В каком сочетании числительное употреблено правильно?", "options": ["двое братьев", "двое подруг", "обоих сестёр", "оба девочки"], "correctIndex": 0, "explanation": "Собирательные числительные (двое, трое) не сочетаются с существительными женского рода: две подруги. Правильно: обеих сестёр, обе девочки."}, {"type": "grammar", "kind": "дополнение", "question": "Выберите правильную форму: «Купите, пожалуйста, пять ___».", "options": ["килограммов апельсинов", "килограмм апельсин", "килограммов апельсин", "килограмм апельсинов"], "correctIndex": 0, "explanation": "Литературная норма в родительном падеже множественного числа: килограммов, апельсинов."}, {"type": "grammar", "kind": "значение", "question": "Какое слово является синонимом к слову «храбрый»?", "options": ["отважный", "трусливый", "хитрый", "спокойный"], "correctIndex": 0, "explanation": "Синонимы близки по значению: храбрый — отважный, смелый."}, {"type": "grammar", "kind": "значение", "question": "Что означает фразеологизм «бить баклуши»?", "options": ["бездельничать", "много работать", "драться", "спорить"], "correctIndex": 0, "explanation": "«Бить баклуши» — праздно проводить время, бездельничать."}, {"type": "grammar", "kind": "значение", "question": "В каком предложении слово «лёгкий» употреблено в переносном значении?", "options": ["У неё лёгкий характер.", "Чемодан оказался лёгким.", "Пух очень лёгкий.", "Лёгкая лодка быстро плыла по реке."], "correctIndex": 0, "explanation": "«Лёгкий характер» — уживчивый, покладистый; это переносное значение. В остальных — прямое: «небольшой по весу»."}, {"type": "grammar", "kind": "значение", "question": "Какой частью речи является слово «вдали»?", "options": ["наречием", "существительным", "предлогом", "прилагательным"], "correctIndex": 0, "explanation": "«Вдали» отвечает на вопрос «где?», не изменяется — это наречие."}, {"type": "grammar", "kind": "значение", "question": "Какое слово является антонимом к слову «щедрый»?", "options": ["скупой", "добрый", "богатый", "честный"], "correctIndex": 0, "explanation": "Антонимы противоположны по значению: щедрый — скупой."}, {"type": "grammar", "kind": "значение", "question": "В каком значении употреблено слово «поля» в предложении «Учитель сделал пометку на полях тетради»?", "options": ["чистая полоса по краю страницы", "участок земли без леса", "область деятельности", "пространство действия какой-либо силы"], "correctIndex": 0, "explanation": "Поля тетради — чистые полосы по краям страницы."}, {"type": "grammar", "kind": "нормы", "question": "В каком слове ударение падает на второй слог?", "options": ["звонИт", "тОрты", "свЁкла", "каталОг"], "correctIndex": 0, "explanation": "Звонить: звонИт, звонИшь. Торты — на первый слог (тОрты), свЁкла — на первый, каталОг — на третий."}, {"type": "grammar", "kind": "нормы", "question": "В каком варианте допущена ошибка?", "options": ["ихний дом", "их дом", "пять килограммов", "лягте на пол"], "correctIndex": 0, "explanation": "Слова «ихний» в литературном языке нет; правильно: их дом."}, {"type": "grammar", "kind": "нормы", "question": "Какое сочетание соответствует норме?", "options": ["более красивый", "более красивее", "самый умнейший", "менее интереснее"], "correctIndex": 0, "explanation": "Нельзя соединять две формы степени сравнения: «более красивее», «самый умнейший» — ошибки."}, {"type": "grammar", "kind": "нормы", "question": "Как правильно прочитать: «в 2005 году»?", "options": ["в две тысячи пятом году", "в двухтысяча пятом году", "в две тысяча пятом году", "в двух тысяч пятом году"], "correctIndex": 0, "explanation": "В составных порядковых числительных изменяется только последнее слово: в две тысячи пятом году."}, {"type": "grammar", "kind": "нормы", "question": "Какое слово женского рода?", "options": ["мозоль", "тюль", "шампунь", "рояль"], "correctIndex": 0, "explanation": "Мозоль — женского рода (натёртая мозоль). Тюль, шампунь, рояль — мужского."}, {"type": "grammar", "kind": "нормы", "question": "В каком сочетании есть лексическая ошибка (лишнее по смыслу слово)?", "options": ["памятный сувенир", "дорогой подарок", "первая встреча", "новый учебник"], "correctIndex": 0, "explanation": "Сувенир — это и есть «подарок на память», слово «памятный» лишнее (плеоназм)."}, {"type": "grammar", "kind": "орфография", "topic": "приставки ПРЕ-/ПРИ-", "question": "В каком слове в приставке на месте пропуска пишется буква И?", "options": ["пр..ехать", "пр..одолеть", "пр..рвать", "пр..старелый"], "correctIndex": 0, "explanation": "Приехать — приставка ПРИ- в значении приближения. Преодолеть и прервать — ПРЕ- близка по значению к ПЕРЕ-, престарелый — ПРЕ- в значении «очень»."}, {"type": "grammar", "kind": "орфография", "topic": "Н/НН в прилагательных", "question": "В каком словосочетании на месте пропуска пишется одна буква Н?", "options": ["стекля..ая ваза", "ветре..ый день", "осе..ий лист", "карти..ая галерея"], "correctIndex": 1, "explanation": "Ветреный — слово-исключение, пишется с одной Н. Стеклянный — исключение с НН; в словах осенний и картинный корень оканчивается на Н и добавляется суффикс -Н-."}, {"type": "grammar", "kind": "орфография", "topic": "чередующиеся гласные в корне", "question": "В каком слове с чередующейся гласной в корне на месте пропуска пишется буква А?", "options": ["пол..жить", "выр..сли", "предл..гать", "к..снуться"], "correctIndex": 2, "explanation": "В корне -лаг-/-лож- перед Г пишется А: предлагать. Положить — перед Ж пишется О; выросли — корень -рос- без СТ и Щ; коснуться — -кос- без суффикса -а- после корня."}, {"type": "grammar", "kind": "орфография", "topic": "разделительные Ъ и Ь", "question": "В каком слове на месте пропуска пишется разделительный Ь, а не Ъ?", "options": ["об..ём", "с..ёмка", "пред..юбилейный", "руч..и"], "correctIndex": 3, "explanation": "Ручьи — разделительный Ь пишется внутри слова не после приставки. В остальных словах Ъ стоит после приставки на согласную перед Е, Ё, Ю, Я."}, {"type": "grammar", "kind": "орфография", "topic": "НЕ с разными частями речи", "question": "В каком предложении НЕ со словом пишется раздельно?", "options": ["Дверь была (не)заперта.", "(Не)смотря на дождь, мы пошли гулять.", "Он (не)годовал из-за опоздания.", "Мы шли по (не)широкой тропинке."], "correctIndex": 0, "explanation": "С краткими причастиями НЕ пишется раздельно: не заперта. Несмотря на (предлог) и негодовать (без НЕ не употребляется) пишутся слитно; неширокой = узкой, поэтому слитно."}, {"type": "grammar", "kind": "орфография", "topic": "-ТСЯ/-ТЬСЯ в глаголах", "question": "В каком предложении на месте пропуска в глаголе пишется Ь?", "options": ["Он часто улыбает..ся.", "Мне нужно научит..ся плавать.", "Вода в реке быстро нагревает..ся.", "Кажет..ся, скоро пойдёт дождь."], "correctIndex": 1, "explanation": "Нужно (что делать?) научиться — неопределённая форма, пишется -ТЬСЯ. В остальных глаголы отвечают на вопрос «что делает?» и пишутся с -ТСЯ."}, {"type": "grammar", "kind": "орфография", "topic": "О/Ё после шипящих", "question": "В каком слове после шипящей на месте пропуска пишется буква О?", "options": ["ж..лтый", "ш..пот", "плеч..м", "ч..рный"], "correctIndex": 2, "explanation": "В окончании существительного под ударением после шипящей пишется О: плечом. В корнях жёлтый (желтеть), шёпот (шептать), чёрный (чернеть) пишется Ё."}, {"type": "grammar", "kind": "орфография", "topic": "дефисное написание наречий", "question": "Какое наречие пишется через дефис?", "options": ["(в)даль", "(на)верху", "(в)низу", "по(английски)"], "correctIndex": 3, "explanation": "Наречия с приставкой ПО- и суффиксом -ски пишутся через дефис: по-английски. Вдаль, наверху, внизу пишутся слитно."}, {"type": "grammar", "kind": "орфография", "topic": "безударные гласные в корне", "question": "В каком слове пропущена непроверяемая безударная гласная корня?", "options": ["в..кзал", "л..сной", "с..стра", "тр..ва"], "correctIndex": 0, "explanation": "Написание слова «вокзал» нужно запомнить (словарное слово). Лесной проверяется словом «лес», сестра — «сёстры», трава — «травы»."}, {"type": "grammar", "kind": "орфография", "topic": "приставки на З/С", "question": "В каком слове на месте пропуска в приставке пишется буква С?", "options": ["бе..дарный", "ра..писание", "и..бежать", "ра..бить"], "correctIndex": 1, "explanation": "Перед глухой согласной (П) пишется приставка РАС-: расписание. Перед звонкими согласными — З: бездарный, избежать, разбить."}, {"type": "grammar", "kind": "орфография", "topic": "Н/НН в причастиях", "question": "В каком словосочетании на месте пропуска пишется НН?", "options": ["варё..ые яйца", "жаре..ая рыба", "прочита..ая книга", "кова..ый сундук"], "correctIndex": 2, "explanation": "Прочитанная — причастие с приставкой, совершенного вида, пишется НН. Варёные, жареная, кованый — отглагольные прилагательные несовершенного вида без приставки и зависимых слов, пишутся с одной Н."}, {"type": "grammar", "kind": "пунктуация", "topic": "запятая при однородных членах", "question": "В каком предложении нужна запятая между однородными членами?", "options": ["Он любил музыку( ) и живопись.", "Возьми ручку( ) или карандаш.", "На столе стояли чай( ) да печенье.", "Он любил не только музыку( ) но и живопись."], "correctIndex": 3, "explanation": "Перед второй частью двойного союза «не только… но и» ставится запятая. Одиночные союзы И, ИЛИ, ДА (в значении И) между однородными членами запятой не отделяются."}, {"type": "grammar", "kind": "пунктуация", "topic": "запятая при причастном обороте", "question": "В каком предложении причастный оборот нужно выделить запятыми?", "options": ["Письмо( ) полученное вчера( ) лежало на столе.", "Полученное вчера( ) письмо лежало на столе.", "Мы долго читали( ) полученное вчера письмо.", "На столе лежало( ) недавно полученное письмо."], "correctIndex": 0, "explanation": "Причастный оборот выделяется запятыми, если стоит после определяемого слова: письмо, полученное вчера. Перед определяемым словом оборот не обособляется."}, {"type": "grammar", "kind": "пунктуация", "topic": "сравнительный оборот", "question": "В каком предложении сравнительный оборот нужно выделить запятыми?", "options": ["Дождь лил( ) как из ведра.", "Озеро( ) как зеркало( ) отражало небо.", "Я советую тебе это( ) как друг.", "Он знал город( ) как свои пять пальцев."], "correctIndex": 1, "explanation": "Сравнительный оборот с союзом КАК выделяется запятыми: озеро, как зеркало, отражало. Не выделяются устойчивые выражения (как из ведра, как свои пять пальцев) и оборот со значением «в качестве» (как друг)."}, {"type": "grammar", "kind": "пунктуация", "topic": "прямая речь", "question": "Какое предложение с прямой речью оформлено правильно?", "options": ["«Я скоро вернусь». — пообещал брат.", "«Я скоро вернусь» — пообещал брат.", "«Я скоро вернусь», — пообещал брат.", "«Я скоро вернусь», — Пообещал брат."], "correctIndex": 2, "explanation": "Если слова автора стоят после прямой речи, после неё ставятся запятая и тире, а слова автора пишутся со строчной буквы. Точка внутри кавычек в этом случае не ставится."}, {"type": "grammar", "kind": "пунктуация", "topic": "тире между подлежащим и сказуемым", "question": "В каком предложении между подлежащим и сказуемым нужно поставить тире?", "options": ["Он( ) мой брат.", "Мой брат( ) не врач.", "Горы( ) словно великаны.", "Бишкек( ) столица Кыргызстана."], "correctIndex": 3, "explanation": "Тире ставится, если подлежащее и сказуемое выражены существительными в именительном падеже без связки. Тире не ставится, если подлежащее — местоимение, перед сказуемым стоит НЕ или сравнительный союз (словно)."}, {"type": "grammar", "kind": "пунктуация", "topic": "двоеточие в бессоюзном сложном предложении", "question": "В каком бессоюзном сложном предложении нужно поставить двоеточие?", "options": ["Я не пошёл гулять( ) на улице шёл сильный дождь.", "Пришла весна( ) растаял снег.", "Светит солнце( ) поют птицы.", "Лес рубят( ) щепки летят."], "correctIndex": 0, "explanation": "Двоеточие ставится, если вторая часть указывает на причину того, о чём говорится в первой (можно вставить «потому что»). В остальных предложениях нужны тире (следствие) или запятая (перечисление)."}, {"type": "grammar", "kind": "пунктуация", "topic": "запятая при деепричастном обороте", "question": "В каком предложении деепричастный оборот нужно выделить запятыми с двух сторон?", "options": ["Он сидел( ) сложа руки.", "Мальчик( ) громко смеясь( ) выбежал во двор.", "Мы шли( ) не спеша.", "Она любила читать( ) лёжа."], "correctIndex": 1, "explanation": "Деепричастный оборот «громко смеясь» стоит в середине предложения и выделяется запятыми с двух сторон. «Сложа руки» — фразеологизм, а «не спеша» и «лёжа» близки к наречиям, поэтому не обособляются."}, {"type": "grammar", "kind": "пунктуация", "topic": "вводные слова", "question": "В каком предложении слово «кажется» является вводным и выделяется запятыми?", "options": ["Задача( ) кажется трудной.", "Мне это( ) кажется странным.", "Он( ) кажется( ) уже ушёл.", "Эта дорога( ) кажется бесконечной."], "correctIndex": 2, "explanation": "В первом предложении «кажется» выражает неуверенность говорящего и не является членом предложения — это вводное слово. В остальных «кажется» — часть сказуемого."}, {"type": "grammar", "kind": "пунктуация", "topic": "обращение", "question": "В каком предложении обращение нужно выделить запятыми с двух сторон?", "options": ["Айбек( ) сделал уроки вечером.", "Я спросил( ) Айбека об уроках.", "С Айбеком( ) мы сделали уроки.", "Скажи( ) Айбек( ) ты сделал уроки?"], "correctIndex": 3, "explanation": "«Айбек» здесь — обращение в середине предложения, оно выделяется запятыми с двух сторон. В остальных предложениях это подлежащее или дополнение."}, {"type": "grammar", "kind": "пунктуация", "topic": "запятая в сложносочинённом предложении", "question": "В каком сложносочинённом предложении запятая перед союзом И НЕ нужна?", "options": ["Вечером подул холодный ветер( ) и пошёл дождь.", "Подул холодный ветер( ) и пошёл дождь.", "Солнце скрылось за тучами( ) и небо потемнело.", "Прозвенел звонок( ) и ученики вышли из класса."], "correctIndex": 0, "explanation": "Если у частей сложносочинённого предложения есть общий второстепенный член (вечером), запятая перед И не ставится. В остальных предложениях общего члена нет, поэтому запятая нужна."}, {"type": "grammar", "kind": "пунктуация", "topic": "запятые в сложноподчинённом предложении", "question": "В каком предложении придаточную часть нужно выделить запятыми с двух сторон?", "options": ["Мы видели дом( ) в котором ты живёшь.", "Дом( ) в котором мы живём( ) построен давно.", "Когда наступит лето( ) мы поедем на Иссык-Куль.", "Он спросил( ) где находится библиотека."], "correctIndex": 1, "explanation": "Придаточное «в котором мы живём» стоит внутри главного предложения, поэтому выделяется запятыми с двух сторон. В остальных придаточное стоит в начале или в конце и отделяется одной запятой."}, {"type": "grammar", "kind": "словообразование", "topic": "суффиксальный способ", "question": "Какое слово образовано суффиксальным способом?", "options": ["прадед", "пригород", "лётчик", "самолёт"], "correctIndex": 2, "explanation": "Лётчик образовано от глагола «летать» с помощью суффикса -чик. Прадед и пригород образованы приставочным способом, самолёт — сложением основ."}, {"type": "grammar", "kind": "словообразование", "topic": "бессуффиксный способ", "question": "Какое слово образовано бессуффиксным способом?", "options": ["синева", "синеватый", "посинеть", "синь"], "correctIndex": 3, "explanation": "Синь образовано от прилагательного «синий» отбрасыванием окончания без добавления суффикса. Синева и синеватый образованы суффиксальным способом, посинеть — приставочным."}, {"type": "grammar", "kind": "словообразование", "topic": "однокоренные слова", "question": "В каком ряду все три слова имеют один и тот же корень (с чередованием гласных)?", "options": ["гореть, загар, огарок", "носить, носилки, носатый", "лес, лесник, лестница", "соль, солонка, солнце"], "correctIndex": 0, "explanation": "Корень -гор-/-гар- (огонь): гореть, загар, огарок. Носатый (от «нос»), лестница и солнце имеют другие корни, лишь похожие по звучанию."}, {"type": "grammar", "kind": "словообразование", "topic": "морфемный состав слова", "question": "Каков морфемный состав слова «перевозчик»?", "options": ["приставка + корень + окончание", "приставка + корень + суффикс + нулевое окончание", "корень + суффикс + окончание", "приставка + корень + два суффикса + нулевое окончание"], "correctIndex": 1, "explanation": "Пере- (приставка) + воз (корень) + -чик (суффикс) + нулевое окончание (перевозчик-а, перевозчик-у)."}, {"type": "grammar", "kind": "словообразование", "topic": "приставочно-суффиксальный способ", "question": "Каким способом образовано наречие «по-новому»?", "options": ["приставочным", "суффиксальным", "приставочно-суффиксальным", "сложением основ"], "correctIndex": 2, "explanation": "По-новому образовано от прилагательного «новый» одновременным присоединением приставки ПО- и суффикса -ему."}, {"type": "grammar", "kind": "словообразование", "topic": "сложносокращённые слова", "question": "Каким способом образовано слово «вуз»?", "options": ["суффиксальным", "приставочным", "переходом из одной части речи в другую", "сложением с сокращением (аббревиация)"], "correctIndex": 3, "explanation": "Вуз — сложносокращённое слово из начальных звуков слов «высшее учебное заведение»."}, {"type": "grammar", "kind": "словообразование", "topic": "переход из одной части речи в другую", "question": "Какое слово образовано переходом из одной части речи в другую?", "options": ["столовая", "столик", "настольный", "застолье"], "correctIndex": 0, "explanation": "Столовая — бывшее прилагательное (столовая комната), ставшее существительным без изменения состава. Остальные слова образованы с помощью суффиксов и приставок."}, {"type": "grammar", "kind": "словообразование", "topic": "однокоренные слова и формы слова", "question": "В какой паре слова являются однокоренными, а не формами одного и того же слова?", "options": ["дом — дома", "дом — домик", "дома — домов", "домом — дому"], "correctIndex": 1, "explanation": "Домик — новое слово с уменьшительным суффиксом -ик-, это однокоренное слово. В остальных парах меняется только окончание — это формы слова «дом»."}, {"type": "grammar", "kind": "словообразование", "topic": "значение суффиксов", "question": "Какой суффикс существительного обозначает детёныша животного?", "options": ["-ищ-", "-тель-", "-онок- (-ёнок-)", "-ость-"], "correctIndex": 2, "explanation": "Суффикс -онок-/-ёнок- обозначает детёныша: волчонок, котёнок. -ищ- обозначает увеличение, -тель- — деятеля, -ость- — отвлечённый признак."}, {"type": "grammar", "kind": "словообразование", "topic": "окончание и нулевое окончание", "question": "В каком слове нет окончания (даже нулевого)?", "options": ["стол", "ночь", "пришёл", "быстро"], "correctIndex": 3, "explanation": "Быстро — наречие, неизменяемое слово, поэтому окончания не имеет. Стол, ночь, пришёл — изменяемые слова с нулевым окончанием."}, {"type": "grammar", "kind": "словообразование", "topic": "производящая основа", "question": "Какое существительное образовано от прилагательного?", "options": ["белизна", "бегун", "читатель", "лесник"], "correctIndex": 0, "explanation": "Белизна образовано от прилагательного «белый» с помощью суффикса -изн-. Бегун и читатель образованы от глаголов, лесник — от существительного."}, {"type": "grammar", "kind": "дополнение", "topic": "предлог «благодаря» с дательным падежом", "question": "Выберите правильную форму: «Я исправил ошибку благодаря ___ учителя».", "options": ["совета", "совету", "советом", "совете"], "correctIndex": 1, "explanation": "Предлог «благодаря» требует дательного падежа: благодаря (чему?) совету."}, {"type": "grammar", "kind": "дополнение", "topic": "предлог «вопреки» с дательным падежом", "question": "Выберите правильную форму: «Вопреки ___ синоптиков день выдался солнечным».", "options": ["прогнозов", "прогнозами", "прогнозам", "прогнозах"], "correctIndex": 2, "explanation": "Предлог «вопреки» требует дательного падежа: вопреки (чему?) прогнозам."}, {"type": "grammar", "kind": "дополнение", "topic": "склонение числительных", "question": "Выберите правильную форму числительного: «Для покупки не хватало ___ сомов».", "options": ["пятиста", "пятьсот", "пятистах", "пятисот"], "correctIndex": 3, "explanation": "В родительном падеже (не хватало чего?) у числительного «пятьсот» изменяются обе части: пятисот."}, {"type": "grammar", "kind": "дополнение", "topic": "заплатить/оплатить", "question": "Выберите подходящее слово: «Не забудьте ___ за проезд в автобусе».", "options": ["заплатить", "оплатить", "оплачивать", "выплатить"], "correctIndex": 0, "explanation": "Заплатить за что: заплатить за проезд. Оплатить что (без предлога): оплатить проезд. Выплатить — выдать деньги (выплатить зарплату)."}, {"type": "grammar", "kind": "дополнение", "topic": "паронимы представить/предоставить", "question": "Выберите подходящее слово: «Студенту ___ место в общежитии».", "options": ["представили", "предоставили", "предъявили", "подставили"], "correctIndex": 1, "explanation": "Предоставить — дать в пользование. Представить — познакомить или показать, предъявить — показать для проверки."}, {"type": "grammar", "kind": "дополнение", "topic": "паронимы абонемент/абонент", "question": "Выберите подходящее слово: «Я купил ___ в бассейн на три месяца».", "options": ["абонент", "абонентский", "абонемент", "абонементный"], "correctIndex": 2, "explanation": "Абонемент — документ на право пользования чем-либо в течение срока. Абонент — тот, кто пользуется связью (телефоном), а прилагательные здесь не подходят грамматически."}, {"type": "grammar", "kind": "дополнение", "topic": "собирательные числительные", "question": "Выберите правильный вариант: «Дорога до Оша заняла ___ суток».", "options": ["два", "две", "двоих", "двое"], "correctIndex": 3, "explanation": "Со словами, имеющими только множественное число (сутки), употребляются собирательные числительные: двое суток."}, {"type": "grammar", "kind": "дополнение", "topic": "предложное управление", "question": "Выберите правильный предлог: «Тренер выразил уверенность ___ победе команды».", "options": ["в", "о", "к", "на"], "correctIndex": 0, "explanation": "Уверенность (в чём?) — в победе. Так же: уверен в успехе."}, {"type": "grammar", "kind": "дополнение", "topic": "управление: уделять внимание", "question": "Выберите правильный вариант: «Учитель уделял большое внимание ___».", "options": ["на развитие речи", "развитию речи", "развития речи", "о развитии речи"], "correctIndex": 1, "explanation": "Уделять внимание (чему?) — развитию речи, без предлога. «Обращать внимание на» — другое выражение, их нельзя смешивать."}, {"type": "grammar", "kind": "дополнение", "topic": "управление: заведующий", "question": "Выберите правильную форму: «Моя мама работает заведующей ___».", "options": ["лаборатории", "лабораторию", "лабораторией", "за лабораторией"], "correctIndex": 2, "explanation": "Заведовать и заведующий требуют творительного падежа: заведовать (чем?) лабораторией."}, {"type": "grammar", "kind": "дополнение", "topic": "склонение числительного «полтора»", "question": "Выберите правильную форму: «До школы около ___ километров».", "options": ["полтора", "полуторых", "полторы", "полутора"], "correctIndex": 3, "explanation": "В косвенных падежах «полтора» имеет форму «полутора»: около полутора километров."}, {"type": "grammar", "kind": "значение", "topic": "фразеологизмы", "question": "Что означает фразеологизм «водить за нос»?", "options": ["обманывать", "помогать", "торопить", "ругать"], "correctIndex": 0, "explanation": "«Водить за нос» — обманывать, вводить в заблуждение, давая пустые обещания."}, {"type": "grammar", "kind": "значение", "topic": "фразеологизмы", "question": "Что означает фразеологизм «работать спустя рукава»?", "options": ["старательно", "небрежно", "быстро", "весело"], "correctIndex": 1, "explanation": "«Спустя рукава» — небрежно, кое-как. Противоположное по смыслу выражение — «засучив рукава»."}, {"type": "grammar", "kind": "значение", "topic": "антонимы", "question": "Какая пара слов является антонимами?", "options": ["смелый — храбрый", "бежать — мчаться", "начало — конец", "дом — домик"], "correctIndex": 2, "explanation": "Антонимы — слова с противоположным значением: начало — конец. Смелый — храбрый и бежать — мчаться — синонимы, дом — домик — однокоренные слова."}, {"type": "grammar", "kind": "значение", "topic": "омонимы", "question": "В какой паре слова являются омонимами?", "options": ["золотое кольцо — золотые руки", "острый нож — острый ум", "идёт человек — идёт дождь", "ключ от двери — холодный ключ (родник)"], "correctIndex": 3, "explanation": "Ключ (для замка) и ключ (родник) — разные слова, одинаковые по звучанию, это омонимы. В остальных парах — значения одного многозначного слова."}, {"type": "grammar", "kind": "значение", "topic": "части речи: производные предлоги", "question": "Какой частью речи является слово «благодаря» в предложении «Благодаря друзьям я справился с трудностями»?", "options": ["предлогом", "деепричастием", "наречием", "союзом"], "correctIndex": 0, "explanation": "Здесь «благодаря» — производный предлог: он утратил значение действия «благодарить» и требует дательного падежа (благодаря друзьям)."}, {"type": "grammar", "kind": "значение", "topic": "лексическое значение слова", "question": "Что означает слово «гостеприимный»?", "options": ["часто бывающий в гостях", "радушно принимающий гостей", "приглашённый в гости", "не любящий гостей"], "correctIndex": 1, "explanation": "Гостеприимный — тот, кто радушно, охотно принимает гостей (гость + принимать)."}, {"type": "grammar", "kind": "значение", "topic": "прямое и переносное значение", "question": "В каком словосочетании слово «золотой» употреблено в прямом значении?", "options": ["золотое сердце", "золотая осень", "золотой перстень", "золотые руки"], "correctIndex": 2, "explanation": "Золотой перстень — сделанный из золота, это прямое значение. Золотое сердце (доброе), золотая осень (жёлтая), золотые руки (умелые) — переносные значения."}, {"type": "grammar", "kind": "значение", "topic": "синонимы", "question": "Какое слово является синонимом слова «неприязнь»?", "options": ["симпатия", "равнодушие", "уважение", "антипатия"], "correctIndex": 3, "explanation": "Неприязнь и антипатия — чувство недоброжелательства к кому-либо. Симпатия — антоним."}, {"type": "grammar", "kind": "значение", "topic": "части речи: числительное", "question": "Какой частью речи является слово «пятеро»?", "options": ["числительным", "наречием", "существительным", "прилагательным"], "correctIndex": 0, "explanation": "Пятеро — собирательное числительное: обозначает количество как совокупность (пятеро друзей)."}, {"type": "grammar", "kind": "значение", "topic": "фразеологизмы", "question": "Что означает фразеологизм «с гулькин нос»?", "options": ["очень много", "очень мало", "очень быстро", "очень далеко"], "correctIndex": 1, "explanation": "«С гулькин нос» — очень мало (гулька — голубь, у которого маленький клюв)."}, {"type": "grammar", "kind": "нормы", "topic": "ударение", "question": "В каком слове ударение поставлено правильно?", "options": ["звОнишь", "тортЫ", "красИвее", "щАвель"], "correctIndex": 2, "explanation": "Правильно: красИвее, звонИшь, тОрты, щавЕль."}, {"type": "grammar", "kind": "нормы", "topic": "ударение", "question": "В каком слове ударение падает на последний слог?", "options": ["свёкла", "шарфы", "кухонный", "квартал"], "correctIndex": 3, "explanation": "Правильно: квартАл — ударение на последнем слоге. СвЁкла, шАрфы, кУхонный — ударение на первом слоге."}, {"type": "grammar", "kind": "нормы", "topic": "ударение в глаголах прошедшего времени", "question": "В какой форме глагола ударение поставлено правильно?", "options": ["началА", "брАла", "пОняла", "звАла"], "correctIndex": 0, "explanation": "В женском роде прошедшего времени у этих глаголов ударение падает на окончание: началА, бралА, понялА, звалА."}, {"type": "grammar", "kind": "нормы", "topic": "род существительных", "question": "Какое существительное мужского рода?", "options": ["вуаль", "картофель", "бандероль", "фасоль"], "correctIndex": 1, "explanation": "Картофель — мужского рода (молодой картофель). Вуаль, бандероль, фасоль — женского рода."}, {"type": "grammar", "kind": "нормы", "topic": "род несклоняемых существительных", "question": "В каком сочетании допущена ошибка в роде несклоняемого существительного?", "options": ["новое пальто", "широкое шоссе", "горячая какао", "интересное интервью"], "correctIndex": 2, "explanation": "Несклоняемые неодушевлённые существительные иностранного происхождения, как правило, среднего рода: горячее какао, новое пальто, широкое шоссе."}, {"type": "grammar", "kind": "нормы", "topic": "формы множественного числа", "question": "Какая форма множественного числа соответствует литературной норме?", "options": ["шофера", "бухгалтера", "торта", "директора"], "correctIndex": 3, "explanation": "Норма: директорА, но шофЁры, бухгАлтеры, тОрты."}, {"type": "grammar", "kind": "нормы", "topic": "родительный падеж множественного числа", "question": "В каком варианте форма родительного падежа множественного числа образована правильно?", "options": ["много помидоров", "пара ботинков", "нет полотенцев", "несколько яблоков"], "correctIndex": 0, "explanation": "Норма: много помидоров, но пара ботинок, нет полотенец, несколько яблок."}, {"type": "grammar", "kind": "нормы", "topic": "плеоназм", "question": "В каком предложении есть лишнее по смыслу слово (плеоназм)?", "options": ["В июле мы поехали в горы.", "В июле месяце мы поехали в горы.", "Летом мы поехали в горы.", "В июле мы отдыхали на озере."], "correctIndex": 1, "explanation": "Июль — это и есть месяц, поэтому слово «месяц» лишнее. Такое повторение смысла называется плеоназмом."}, {"type": "grammar", "kind": "нормы", "topic": "лексическая сочетаемость", "question": "В каком сочетании нарушена лексическая сочетаемость?", "options": ["играть роль", "иметь значение", "играть значение", "принять участие"], "correctIndex": 2, "explanation": "Правильно: играть роль или иметь значение. «Играть значение» — смешение двух выражений."}, {"type": "grammar", "kind": "нормы", "topic": "формы глагола", "question": "Какая форма глагола соответствует литературной норме?", "options": ["они хочут", "он хотит", "мы хочем", "они хотят"], "correctIndex": 3, "explanation": "Глагол «хотеть» спрягается смешанно: хочу, хочешь, хочет, но хотим, хотите, хотят."}]};
